window.HISN_DATA = {"chapters":[{"id":1,"title":"أذكار الاستيقاظ من النوم","url":"https://www.imadislam.com/hisnulmuslim/001.htm","entries":[{"number":1,"text":"\" الحَمْدُ لله الذِي أحْيَانا بَعْدَ مَا أمَاتَنَا* وإلَيْهِ النَشُور* \"[1]","key":"1-0","references":[{"number":"1","text":"البخاري مع الفتح 11/ 113 ومسلم 4/ 2083."}]},{"number":2,"text":"\" الحَمْدُ لله الذِي عَافَانِي في جَسَدِي ورَدَّ عَلَيَّ رُوحِي، وأَذِنَ لي بِذِكْرهِ \"[2].","key":"1-1","references":[{"number":"2","text":"الترمذي 5/ 473 وانظر صحيح الترمذي3/144"}]},{"number":3,"text":"قال رسول الله صلى الله عليه وسلم \" مَنْ تَعَارَ مِنَ اللَّيْل* فقال حين يستيقظ :\" لا إلَهَ إلاَّ الله وحْدَهُ لا شَرِيكَ لَهُ، لَهُ المُلْكُ ولَهُ الحَمْدُ وهُوَ على كلِّ شيءٍ قَدير،سُبْحانَ الله والحَمْدُ لله ولا إله إلا الله والله أكبر ولا حَولَ ولا قُوةَ إلا بالله العلي العظيم \" ثم دعا: \" اللَّهُمَّ اغْفِرْ لي، غُفِرَ له \"، قال الوليد: أو قال: \" دعا استُجيبَ لهُ، فإن قام فتوضأَ ثم صَلّى قُبِلَتْ صَلاتُهُ \".[3]","key":"1-2","references":[{"number":"3","text":"رواه البخاري مع الفتح 3/ 144 وغيرها واللفظ لابن ماجه انظر صحيح ابن ماجه 2/ 335 ."}]},{"number":4,"text":"{إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالأَرْضِ وَاخْتِلاَفِ اللَّيْلِ وَالنَّهَارِ لآيَاتٍ لِّأُوْلِي الألْبَابِ *الَّذِينَ يَذْكُرُونَ اللّهَ قِيَاماً وَقُعُوداً وَعَلَىَ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِي خَلْقِ السَّمَاوَاتِ وَالأَرْضِ رَبَّنَا مَا خَلَقْتَ هَذا بَاطِلاً سُبْحَانَكَ فَقِنَا عَذَابَ النَّارِ*رَبَّنَا إِنَّكَ مَن تُدْخِلِ النَّارَ فَقَدْ أَخْزَيْتَهُ وَمَا لِلظَّالِمِينَ مِنْ أَنصَارٍ *رَّبَّنَا إِنَّنَا سَمِعْنَا مُنَادِياً يُنَادِي لِلإِيمَانِ أَنْ آمِنُواْ بِرَبِّكُمْ فَآمَنَّا رَبَّنَا فَاغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّئَاتِنَا وَتَوَفَّنَا مَعَ الأبْرَارِ * رَبَّنَا وَآتِنَا مَا وَعَدتَّنَا عَلَى رُسُلِكَ وَلاَ تُخْزِنَا يَوْمَ الْقِيَامَةِ إِنَّكَ لاَ تُخْلِفُ الْمِيعَادَ *فَاسْتَجَابَ لَهُمْ رَبُّهُمْ أَنِّي لاَ أُضِيعُ عَمَلَ عَامِلٍ مِّنكُم مِّن ذَكَرٍ أَوْ أُنثَى بَعْضُكُم مِّن بَعْضٍ فَالَّذِينَ هَاجَرُواْ وَأُخْرِجُواْ مِن دِيَارِهِمْ وَأُوذُواْ فِي سَبِيلِي وَقَاتَلُواْ وَقُتِلُواْ لأُكَفِّرَنَّ عَنْهُمْ سَيِّئَاتِهِمْ وَلأُدْخِلَنَّهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الأَنْهَارُ ثَوَاباً مِّن عِندِ اللّهِ وَاللّهُ عِندَهُ حُسْنُ الثَّوَابِ *لاَ يَغُرَّنَّكَ تَقَلُّبُ الَّذِينَ كَفَرُواْ فِي الْبِلاَدِ *مَتَاعٌ قَلِيلٌ ثُمَّ مَأْوَاهُمْ جَهَنَّمُ وَبِئْسَ الْمِهَادُ *لَكِنِ الَّذِينَ اتَّقَوْاْ رَبَّهُمْ لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الأَنْهَارُ خَالِدِينَ فِيهَا نُزُلاً مِّنْ عِندِ اللّهِ وَمَا عِندَ اللّهِ خَيْرٌ لِّلأَبْرَارِ * وَإِنَّ مِنْ أَهْلِ الْكِتَابِ لَمَن يُؤْمِنُ بِاللّهِ وَمَا أُنزِلَ إِلَيْكُمْ وَمَا أُنزِلَ إِلَيْهِمْ خَاشِعِينَ لِلّهِ لاَ يَشْتَرُونَ بِآيَاتِ اللّهِ ثَمَناً قَلِيلاً أُوْلَـئِكَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ إِنَّ اللّهَ سَرِيعُ الْحِسَابِ *يَا أَيُّهَا الَّذِينَ آمَنُواْ اصْبِرُواْ وَصَابِرُواْ وَرَابِطُواْ وَاتَّقُواْ اللّهَ لَعَلَّكُمْ تُفْلِحُونَ }[4]","key":"1-3","references":[{"number":"4","text":"الآيات من سورة آل عمران ،190 — 200 ، البخاري مع الفتح 8/ 238 ومسلم 1/ 530"}]}],"extraReferences":[{"number":"5","text":"* التعار السهر والتقلب على الفراش ليلاً مع الكلام."}]},{"id":2,"title":"دعاء لبس الثوب","url":"https://www.imadislam.com/hisnulmuslim/002.htm","entries":[{"number":5,"text":"مَنْ لَبِسَ ثَوْباًً فقال: الحَمْدُ لله الذِي كَساني هذا( الثوب ) ورَزَقَنِيه مِنْ غَيْرِ حَوْلٍ مِنّي ولا قُوةٍ\"[1]","key":"2-0","references":[{"number":"1","text":"أخرجه أهل السنن إلا النسائي انظر إرواء الغليل 7/ 47 ."}]}],"extraReferences":[]},{"id":3,"title":"دعاء لبس الثوب الجديد","url":"https://www.imadislam.com/hisnulmuslim/003.htm","entries":[{"number":6,"text":"\" اللَّهُمَّ لَكَ الحَمْدُ أَنْتَ كَسَوتَنِيه،أسْألك مِنْ خَيرِهِ وخَيْرَ ما صُنع لَهُ،وأعُوذُ بِكَ مِنْ شرِّه وشَرَّ ما صُنِعَ لَهُ \"[1]","key":"3-0","references":[{"number":"1","text":"— أبو داود والترمذي والبغوي وانظر مختصر شمائل الترمذي للألباني ص 47"}]}],"extraReferences":[]},{"id":4,"title":"الدعاء لمن لبس ثوباً جديداً","url":"https://www.imadislam.com/hisnulmuslim/004.htm","entries":[{"number":7,"text":"\" إلبِسْ جَدِيداً وعِشْ حميداً ومُتْ شهيداً \"[1].","key":"4-0","references":[{"number":"1","text":"ابن ماجه 2/ 1178 والبغوي 12/ 41 وانظر صحيح ابن ماجة2/ 275"}]},{"number":8,"text":"\" تُبْلي ويَخْلِفُ الله تعالى \"[2].","key":"4-1","references":[{"number":"2","text":"أخرجه أبو داود 4/ 41 ، وانظر صحيح أبي داود2/ 760"}]}],"extraReferences":[]},{"id":5,"title":"ما يقول إذا وضع الثوب","url":"https://www.imadislam.com/hisnulmuslim/005.htm","entries":[{"number":9,"text":"سِتْرُ ما بَيْنَ أعْيُن الجِنِّ وَعَوْرَاتِ بَني آدَمَ إذا وَضَعَ أحدُهُمْ ثَوْبَهُ أنْ يقول: \" بِسم الله \"[1].","key":"5-0","references":[{"number":"1","text":"الترمذي 2/505 وغيره وانظر الإرواء برقم 49 صحيح الجامع3/ 203"}]}],"extraReferences":[]},{"id":6,"title":"دعاء دخول الخلاء","url":"https://www.imadislam.com/hisnulmuslim/006.htm","entries":[{"number":10,"text":"{بسم الله}، اللهُمَّ إنّي أعُوذُ بِكَ مِنَ الخُبْثِ والخبائِثِ\"[1].","key":"6-0","references":[{"number":"1","text":"أخرجه البخاري 1/ 45ومسلم1/283وزيادة بسم الله في أوله متفق عليه، أخرجها سعيد بن منصور أنظر فتح الباري 1/244"}]}],"extraReferences":[]},{"id":7,"title":"دعاء الخروج من الخلاء","url":"https://www.imadislam.com/hisnulmuslim/007.htm","entries":[{"number":11,"text":"\" غُفْرانَكَ \"[1].","key":"7-0","references":[{"number":"1","text":"أخرجه أصحاب السنن إلا النسائي أخرجه في عمل اليوم والليلة انظر تخريج زاد المعاد 2/ 387"}]}],"extraReferences":[]},{"id":8,"title":"الذكر قبل الوضوء","url":"https://www.imadislam.com/hisnulmuslim/008.htm","entries":[{"number":12,"text":"\" بسم الله \"[1]","key":"8-0","references":[{"number":"1","text":"أبو داود وابن ماجه وأحمد وانظر إرواء الغليل 1/ 122 ."}]}],"extraReferences":[]},{"id":9,"title":"الذكر بعد الفراغ من الوضوء","url":"https://www.imadislam.com/hisnulmuslim/009.htm","entries":[{"number":13,"text":"\"أشهد أن لا إله إلا الله وحده لا شريك له ، وأشهد أن محمداً عبده ورسوله\"[1]","key":"9-0","references":[{"number":"1","text":"رواه مسلم1/ 209"}]},{"number":14,"text":"وزاد الترمذي بعد ذكر الشهادتين :\"اللهم اجعلني من التوابين واجعلني من المتطهرين\"[2]","key":"9-1","references":[{"number":"2","text":"الترمذي 1/ 78 وانظر صحيح الترمذي1/ 18"}]},{"number":15,"text":"\"سبحانك اللهم وبحمدك أشهد أن لا إله إلا أنت أستغفرك وأتوب إليك\"[3].","key":"9-2","references":[{"number":"3","text":"النسائي في عمل اليوم والليلة ص173 وانظر إرواء الغليل 1/ 135 و2/ 94"}]}],"extraReferences":[]},{"id":10,"title":"الذكر عند الخروج من المنزل","url":"https://www.imadislam.com/hisnulmuslim/010.htm","entries":[{"number":16,"text":"\" بسم الله ، توكَّلْتُ على الله ، ولا حَوْلَ ولا قُوةَ إلا بالله \"[1]","key":"10-0","references":[{"number":"1","text":"أبو داود 4/ 325 والترمذي 5/ 490 وانظر صحيح الترمذي3/ 151 ."}]},{"number":17,"text":"\" اللهُمَ إني أعُوذُ بِكَ أن أَضِلَّ أوْ أُضَلَّ أَوْ أزِلَّ، أو أُزَلَّ، أوْ أظلِم أوْ أُظْلَم، أوْ أَجْهَلَ أوْ يُجْهَلَ عَلَيَّ \"[2].","key":"10-1","references":[{"number":"2","text":"أهل السنن وانظر صحيح الترمذي 3/ 152 وصحيح ابن ماجه 2/ 336 ."}]}],"extraReferences":[]},{"id":11,"title":"الذكر عند الدخول المنزل","url":"https://www.imadislam.com/hisnulmuslim/011.htm","entries":[{"number":18,"text":"\"بسم الله ولجنا ،وبسم الله خرجنا ، وعلى ربنا توكلنا ، ثم ليسلم على أهله\"[1]","key":"11-0","references":[{"number":"1","text":"أخرجه أبو داود 4/ 325 ، وحسن إسناده العلامة ابن باز في تحفة الأخيار ص28 ، وفي الصحيح \" إذا دخل الرجل بيته فذكر بيته فذكر الله عند دخوله وعند طعامه قال الشيطان لا مبيت لكم ولا عشاء \" مسلم برقم 2018"}]}],"extraReferences":[]},{"id":12,"title":"دعاء الذهاب إلى المسجد","url":"https://www.imadislam.com/hisnulmuslim/012.htm","entries":[{"number":19,"text":"\" اللهم اجعل في قلبي نوراً ، وفي لساني نوراً ، وفي سمعي نوراً ، وفي بصري نوراً ، ومن فوقي نوراً ، ومن تحتي نوراً ، وعن يميني نوراً ، وعن شمالي نوراً ، ومن أمامي نوراً ، ومن خلفي نوراً ، و اجعل في نفسي نوراً ، وأعظم لي نوراً ، وعظم لي نوراً ، واجعل لي نوراً ، واجعلني نوراً ، اللهم أعطني نوراً ، واجعل في عصبي نوراً ، وفي لحمي نوراً ، وفي دمي نوراً ، وفي شعري نوراً ، وفي بشري نوراً \"[1].\n\" [ اللهم اجعل لي نوراً في قبري .. ونوراً في عظامي ] \"[2] [ \" وزدني نوراً ، وزدني نوراً ، وزدني نوراً \"][3][ \" وهب لي نوراً على نوراً \"][4]","key":"12-0","references":[{"number":"1","text":"جميع هذه الخصال في البخاري 11/ 116 برقم 6316 ومسلم 1/ 526، 529 ، 530 برقم 763"},{"number":"2","text":"الترمذي برقم 3419، 5/483"},{"number":"3","text":"أخرجه البخاري في الأدب المفرد برقم 695 ، ص 258 وصحح إسناده الألباني في صحيح الأدب المفرد برقم 536."},{"number":"4","text":"ذكره ابن حجر في فتح الباري وعزاه إلى ابن أبي عاصم في كتاب الدعاء،انظر الفتح11/118وقال:فاجتمع من اختلاف الروايات خمس وعشرون خصلة"}]}],"extraReferences":[]},{"id":13,"title":"دعاء دخول المسجد","url":"https://www.imadislam.com/hisnulmuslim/013.htm","entries":[{"number":20,"text":"\" أعوذ بالله العظيم ،وبوجهه الكريم ،وسلطانه القديم ،من الشيطان الرجيم \"[1]\n\"[ بسم الله ،والصلاة ][2] [ والسلام على رسول الله][3] ،\" اللهم افتح لي أبواب رحمتك\"[4]","key":"13-0","references":[{"number":"1","text":"أبو داود وانظر صحيح الجامع برقم 4591"},{"number":"2","text":"رواه ابن السني برقم 88 وحسنه الألباني"},{"number":"3","text":"أبو داود 1/ 126 وانظر صحيح الجامع 1/ 528"},{"number":"4","text":"رواه مسلم1/ 494. وفي سنن ابن ماجه من حديث فاطمة رضي الله عنها \" اللهم اغفر لي ذنوبي وافتح لي أبواب رحمتك \" وصححه الألباني لشواهده انظر صحيح ابن ماجه 1/ 128 — 129"}]}],"extraReferences":[]},{"id":14,"title":"دعاء الخروج من المسجد","url":"https://www.imadislam.com/hisnulmuslim/014.htm","entries":[{"number":21,"text":"\" بسم الله والصلاة والسلام على رسول الله ،اللهم إني أسألك من فضلك، اللهم اعصمني من الشيطان الرجيم \"[1]","key":"14-0","references":[{"number":"1","text":"انظر تخريج روايات الحديث السابق رقم 20 وزيادة (( اللهم اعصمني من الشيطان الرجيم )) لابن ماجه . انظر صحيح ابن ماجه 1/ 288"}]}],"extraReferences":[]},{"id":15,"title":"أذكار الأذان","url":"https://www.imadislam.com/hisnulmuslim/015.htm","entries":[{"number":22,"text":"يقول مثل ما يقول المؤذن إلا في \"حي على الصلاة ، وحي على الفلاح\" فيقول \"لا حول ولا قوة إلا بالله\"[1].","key":"15-0","references":[{"number":"1","text":"البخاري 1/ 152 ومسلم 1/ 288"}]},{"number":23,"text":"يقول \" وأنا أشهد أن لا إله إلا الله ، وحده لا شريك له ، وأن محمد عبده ورسوله ، رضيت بالله رباً ، وبمحمداً رسولاً وبالإسلام ديناً\"[2] (( يقول ذلك عقب تشهد المؤذن)) [3]","key":"15-1","references":[{"number":"2","text":"مسلم 1/290"},{"number":"3","text":"ابن خزيمة 1/ 220"}]},{"number":24,"text":"\"يصلي على النبي صلى الله عليه وسلم بعد فراغه من إجابة المؤذن\"[4]","key":"15-2","references":[{"number":"4","text":"مسلم 1/ 288"}]},{"number":25,"text":"\"اللهم رب هذه الدعوة التامة ،والصلاة القائمة، آت محمداً الوسيلة والفضيلة، وأبعثه مقاماً محموداً الذي وعدته، [ إنك لا تخلف الميعاد ][5] .","key":"15-3","references":[{"number":"5","text":"البخاري 1/ 152 وما بين المعكوفين للبيهقي 1/ 410 وحسن إسناده العلامة عبد العزيز بن باز في تحفة الأخيار ص 38 ."}]},{"number":26,"text":"\"يدعو لنفسه بين الأذان والإقامة فإن الدعاء حينئذٍ لا يرد \"[6]","key":"15-4","references":[{"number":"6","text":"الترمذي وأبو داود وأحمد وانظر إرواء الغليل 1/ 262"}]}],"extraReferences":[]},{"id":16,"title":"دعاء الاستفتاح","url":"https://www.imadislam.com/hisnulmuslim/016.htm","entries":[{"number":27,"text":"\"اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب ، اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس اللهم اغسلني من خطاياي بالماء والثلج والبرد \"[1]","key":"16-0","references":[{"number":"1","text":"البخاري 1/ 181 ومسلم 1/ 419"}]},{"number":28,"text":"\"سبحانك اللهم وبحمدك وتبارك اسمك وتعالى جدك، ولا إله غيرك\" [2]","key":"16-1","references":[{"number":"2","text":"أخرجه أصحاب السنن الأربعة وانظر صحيح الترمذي 1/77 وصحيح ابن ماجه 1/ 135"}]},{"number":29,"text":"\"وجهت وجهي للذي فطر السموات والأرض حنيفاً وما أنا من المشركين ،إن صلاتي ونُسُكي ومحياي ومماتي لله رب العالمين ، لا شريك له وبذلك أمرت وأنا من المسلمين اللهم أنت الملك لا إله إلا أنت ، أنت ربي وأنا عبدك ، ظلمت نفسي ، واعترفت بذنبي ، فاغفر لي ذنوبي جميعاً ، إنه لا يغفر الذنوب إلا أنت ، واهدني لأحسن الأخلاق، لا يهدي لأحسنها إلا أنت ، واصرف عني سيئها لا يصرف عني سيئها إلا أنت لبيك وسعديك والخير كله بيديك ، والشر ليس إليك ، أنا بك وإليك ، تباركت وتعاليت أستغفرك وأتوب إليك \"[3]","key":"16-2","references":[{"number":"3","text":"رواه مسلم1/ 534"}]},{"number":30,"text":"\"اللهم رب جبرائيل وميكائيل وإسرافيل ، فاطر السموات والأرض ، عالم الغيب والشهادة ، أنت تحكم بين عبادك فيما كانوا فيه يختلفون اهدني لما اختلف فيه من الحق بإذنك إنك تهدي من تشاء إلى صراط مستقيم \"[4]","key":"16-3","references":[{"number":"4","text":"رواه مسلم1/ 534"}]},{"number":31,"text":"\"الله اكبر كبيرا، الله اكبر كبيرا، الله اكبر كبيرا، والحمد لله كثيرا، والحمد لله كثيرا، والحمد لله كثيرا، وسبحان الله بكرةً وأصيلا ـ ثلاثا ـ \" أعوذ بالله من الشيطان الرجيم : من نفخه، ونفثه ،و همزه \"[5]","key":"16-4","references":[{"number":"5","text":"أخرجه أبو داود 1/ 203 وابن ماجه 1/ 265 وأحمد 4/85 وأخرجه مسلم عن ابن عمر رضي الله عنهماا بنحوه وفيه قصة 1/ 420"}]},{"number":32,"text":"كان النبي صلى الله عليه وسلم إذا قام من الليل يتهجد قال: \" اللهم لك الحمد أنت نور السموات والأرض ومن فيهن ، ولك الحمد أنت قيمُ السموات والأرض ومن فيهن [ ولك الحمد أنت رب السموات والأرض ومن فيهن ]، [ ولك الحمد لك ملك السموات والأرض ومن فيهن ] [ ولك الحمد أنت ملك السموات والأرض] [ ولك الحمد] أنت الحق ، ووعدك الحق ، وقولك الحق ،ولقاؤك الحق ، والجنة حق ، والنار حق ، والنبيّون حق ومحمد صلى الله عليه وسلم حق والساعة حق ] [اللهم لك أسلمت ، وعليك توكلت ، وبك آمنت ، وإليك أنبت ، وبك خاصمت ، وإليك حاكمت ، فاغفر لي ما قدمت وما أخرت ، وأسررت، وما أعلنت ][ أنت المقدم ،وأنت المؤخر لا إله إلا أنت ][أنت إلهي لا إله إلا أنت][6]","key":"16-5","references":[{"number":"6","text":"البخاري مع الفتح 3/3 و11/116 و 13/ 371 423، 465 ومسلم مختصراً بنحوه 1/ 532"}]}],"extraReferences":[]},{"id":17,"title":"دعاء الركوع","url":"https://www.imadislam.com/hisnulmuslim/017.htm","entries":[{"number":33,"text":"\" سبحان ربي العظيم \" ثلاث مرات[1] .","key":"17-0","references":[{"number":"1","text":"أخرجه أهل السنن وأحمد وانظر صحيح الترمذي 1/83"}]},{"number":34,"text":"\" سبحانك اللهم ربنا وبحمدك ، اللهم اغفر لي \"[2]","key":"17-1","references":[{"number":"2","text":"البخاري 1/199ومسلم 1/ 350"}]},{"number":35,"text":"\"سبوح قدوس رب الملائكة والروح\"[3] ،","key":"17-2","references":[{"number":"3","text":"مسلم1/ 353 وأبو داود 1/230"}]},{"number":36,"text":"\"اللهم لك ركعت وبك آمنت ،ولك أسلمت خشع لك سمعي وبصري ودمي ولحمي وعظمي وعصبي،وما استقل به قدمي \"[4]","key":"17-3","references":[{"number":"4","text":"مسلم 1/534والأربعة إلا ابن ماجه"}]},{"number":37,"text":"\" سبحان ذي الجبروت والملكوت والكبرياء والعظمة \"[5].","key":"17-4","references":[{"number":"5","text":"أبو داود 1/ 230 والنسائي وأحمد وإسناده حسن"}]}],"extraReferences":[]},{"id":18,"title":"دعاء الرفع من الركوع","url":"https://www.imadislam.com/hisnulmuslim/018.htm","entries":[{"number":38,"text":"\" سمع الله لمن حمده \"[1] .","key":"18-0","references":[{"number":"1","text":"البخاري مع الفتح 2/ 282"}]},{"number":39,"text":"\"ربنا ولك الحمد ، حمداً كثيراً طيباً مباركاً فيه \"[2]","key":"18-1","references":[{"number":"2","text":"البخاري مع الفتح 2/ 282"}]},{"number":40,"text":"\"....ملء السموات وملء الأرض وما بينهما ، وملء ما شئت من شئ بعد .أهل الثناء والمجد،أحق ما قال العبد، وكلنا لك عبد ، اللهم لا مانع لما أعطيت ولا معطي لما منعت ولا ينفع ذا الجد منك الجد \"[3]","key":"18-2","references":[{"number":"3","text":"مسلم 1/ 346"}]}],"extraReferences":[]},{"id":19,"title":"دعاء السجود","url":"https://www.imadislam.com/hisnulmuslim/019.htm","entries":[{"number":41,"text":"\" سبحان ربي الأعلى \" ، ثلاث مرات .[1]","key":"19-0","references":[{"number":"1","text":"أخرجه أهل السنن وأحمد وانظر صحيح الترمذي 1/83"}]},{"number":42,"text":"\"سبحانك اللهم ربنا وبحمدك ، اللهم اغفر لي \"[2]","key":"19-1","references":[{"number":"2","text":"البخاري ومسلم وتقدم تخريجه برقم 34."}]},{"number":43,"text":"\" سبوح قدوس رب الملائكة والروح \"[3]","key":"19-2","references":[{"number":"3","text":"مسلم 1/ 533وتقدم برقم 35."}]},{"number":44,"text":"\" اللهم لك سجدت وبك آمنت ولك أسلمت،سجد وجهي للذي خلقه وصوره وشق سمعه وبصره تبارك الله أحسن الخالقين \"[4] .","key":"19-3","references":[{"number":"4","text":"مسلم1/ 534 وغيره"}]},{"number":45,"text":"\" سبحان ذي الجبروت والملكوت ، والكبرياء والعظمة \"[5].","key":"19-4","references":[{"number":"5","text":"أبو داود 1/ 230 والنسائي وأحمد وإسناده وصححه الألباني في صحيح أبي داود 166."}]},{"number":46,"text":"\" اللهم اغفر لي ذنبي كله ، دقه وجله ،وأوله وآخره ،وعلانيته وسره \"[6]","key":"19-5","references":[{"number":"6","text":"مسلم1/ 350"}]},{"number":47,"text":"\" اللهم إني أعوذ برضاك من سخطك وبمعافاتك من عقوبتك،وأعوذ بك منك لا أحصي ثناء عليك أنت كما أثنيت على نفسك \"[7] .","key":"19-6","references":[{"number":"7","text":"مسلم1/ 352"}]}],"extraReferences":[]},{"id":20,"title":"دعاء الجلسة بين السجدتين","url":"https://www.imadislam.com/hisnulmuslim/020.htm","entries":[{"number":48,"text":"\" رب اغفر لي ، رب اغفر لي \"[1]","key":"20-0","references":[{"number":"1","text":"أبو داود 1/ 231وانظر صحيح ابن ماجة1/ 148"}]},{"number":49,"text":"\" اللهم اغفر لي ، وارحمني ،واهدني ، واجبرني، وعافني،وارزقني ، وارفعني \"[2].","key":"20-1","references":[{"number":"2","text":"أخرجه أصحاب السنن إلا النسائي وانظر صحيح الترمذي 1/90 وصحيح ابن ماجه 1/ 148 ."}]}],"extraReferences":[]},{"id":21,"title":"دعاء سجود التلاوة","url":"https://www.imadislam.com/hisnulmuslim/021.htm","entries":[{"number":50,"text":"\" سجد وجهي للذي خلقه ، وشق سمعه وبصره بحوله وقوته { فتبارك الله أحسن الخالقين }\"[1]","key":"21-0","references":[{"number":"1","text":"الترمذي 2/474 وأحمد 6/30 والحاكم وصححه ووافقه الذهبي 1/ 220 والزيادة له ."}]},{"number":51,"text":"\" اللهم أكتب لي بها عندك أجراً ، وضع عني بها وزراً ، واجعلها لي عندك ذخراً ، وتقبلها مني كما تقبلتها من عبدك داود \"[2].","key":"21-1","references":[{"number":"2","text":"الترمذي 2/473 والحاكم وصححه ووافقه الذهبي 1/ 219"}]}],"extraReferences":[]},{"id":22,"title":"التشهد","url":"https://www.imadislam.com/hisnulmuslim/022.htm","entries":[{"number":52,"text":"\"التحيات لله ، والصلوات ، والطيبات ، السلام عليك أيها النبي ورحمة الله وبركاته ، السلام علينا وعلى عباد الله الصالحين ،أشهد أن لا إله إلا الله ، وأشهد أن محمداً عبده ورسوله \"[1].","key":"22-0","references":[{"number":"1","text":"البخاري مع الفتح 1/13 ومسلم 1/ 301."}]}],"extraReferences":[]},{"id":23,"title":"الصلاة على النبي صلى الله عليه وسلم بعد التشهد","url":"https://www.imadislam.com/hisnulmuslim/023.htm","entries":[{"number":53,"text":"\" اللهم صل على محمد وعلى آل محمد ، كما صليت على إبراهيم ، وعلى آل إبراهيم ، إنك حميد مجيد ، اللهم بارك على محمد وعلى آل محمد كما باركت على إبراهيم ، وعلى آل إبراهيم إنك حميد مجيد \"[1]","key":"23-0","references":[{"number":"1","text":"البخاري مع الفتح 6/ 408"}]},{"number":54,"text":"\" اللهم صل على محمد وعلى أزواجه وذريته،كما صليت على آل إبراهيم، وبارك على محمد وعلى أزواجه وذريته كما باركت على آل إبراهيم إنك حميد مجيد\" [2]..","key":"23-1","references":[{"number":"2","text":"البخاري مع الفتح 6/ 407ومسلم 1/ 306 واللفظ له"}]}],"extraReferences":[]},{"id":24,"title":"الدعاء بعد التشهد الأخير وقبل السلام","url":"https://www.imadislam.com/hisnulmuslim/024.htm","entries":[{"number":55,"text":"\" اللهم إني أعوذ بك من عذاب القبر،ومن عذاب جهنم،ومن فتنة المحيا والممات ،ومن شر فتنة المسيح الدجال\"[1]","key":"24-0","references":[{"number":"1","text":"البخاري 2/ 102 ومسلم 1/ 412 واللفظ لمسلم"}]},{"number":56,"text":"\" اللهم إني أعوذ بك من عذاب القبر،وأعوذ بك من فتنة المسيح الدجال،وأعوذ بك من فتنة المحيا والممات، اللهم إني أعوذ بك من المأثم والمغرم \"[2]","key":"24-1","references":[{"number":"2","text":"البخاري 1/ 202 ومسلم 1/ 412"}]},{"number":57,"text":"\" اللهم إني ظلمت نفسي ظلماً كثيراً ، ولا يغفر الذنوب إلا أنت ، فاغفر لي مغفرة من عندك وارحمني إنك أنت الغفور الرحيم \"[3]","key":"24-2","references":[{"number":"3","text":"البخاري 8/168 ومسلم 4/ 2078"}]},{"number":58,"text":"\" اللهم اغفر لي ما قدمت وما أخرت وما أسررت وما أعلنت وما أسرفت وما أنت أعلم به مني أنت المقدم وأنت المؤخر لا إله إلا أنت \"[4].","key":"24-3","references":[{"number":"4","text":"مسلم 1/ 534"}]},{"number":59,"text":"\" اللهم أعني على ذكرك ، وشكرك وحسن عبادتك \"[5]","key":"24-4","references":[{"number":"5","text":"أبو داود 2/ 86والنسائي 3/ 53 وصححه الألباني في صحيح أبو داود 1/ 284"}]},{"number":60,"text":"\" اللهم إني أعوذ بك من البخل وأعوذ بك من الجبن ، وأعوذ بك من أن أرد إلى أرذل العمر ، وأعوذ بك من فتنة الدنيا وأعوذ بك من عذاب القبر \"[6].","key":"24-5","references":[{"number":"6","text":"البخاري 6/35"}]},{"number":61,"text":"\" اللهم إني أسألك الجنة وأعوذ بك من النار \"[7] .","key":"24-6","references":[{"number":"7","text":"أبو داود وانظر صحيح ابن ماجه 2/ 328"}]},{"number":62,"text":"\" اللهم بعلمك الغيب وقدرتك على الخلق أحيني ما علمت الحياة خيراً لي وتوفني إذا علمت الوفاة خيراً لي ، اللهم إني أسألك خشيتك في الغيب والشهادة ، وأسألك كلمة الحق في الرضا والغضب ، وأسألك القصد في الغنى والفقر ، وأسألك نعيماً لا ينفد ، وأسألك قرة عين لا تنقطع ، وأسألك الرضا بعد القضاء ، وأسألك برد العيش بعد الموت ، وأسألك لذة النظر إلى وجهك والشوق إلى لقائك من غير ضرَّاء مضرة ولا فتنة مضلة ، اللهم زينا بزينة الإيمان ، واجعلنا هداة مهتدين \"[8] .","key":"24-7","references":[{"number":"8","text":"النسائي 4/54،55وأحمد 4/364 وصححه الألباني في صحيح النسائي 1/ 281"}]},{"number":63,"text":"\" اللهم إني أسألك يا الله بأنك الواحد الأحد الصمد الذي لم يلد ولم يولد ولم يكن له كفواً أحد أن تغفر لي ذنوبي إنك أنت الغفور الرحيم \"[9].","key":"24-8","references":[{"number":"9","text":"أخرجه النسائي بلفظه 3/52وأحمد 4/338 وصححه الألباني في صحيح النسائي 1/ 280"}]},{"number":64,"text":"\" اللهم إني أسألك بأن لك الحمد ، لا إله إلا أنت وحدك لا شريك لك ، المنان ، يا بديع السموات والأرض يا ذا الجلال والإكرام يا حي يا قيوم إني أسألك الجنة وأعوذ بك من النار \"[10].","key":"24-9","references":[{"number":"10","text":"رواه أهل السنن وانظر صحيح ابن ماجه 2/ 329"}]},{"number":65,"text":"\" اللهم إني أسألك بأني أشهد أنك أنت الله لا إله إلا أنت،الأحد الصمد الذي لم يلد ولم يولد ولم يكن له كفواً أحد\"[11].","key":"24-10","references":[{"number":"11","text":"أبو داود2/62والترمذي 5/ 515 وابن ماجه 2/ 1267 وأحمد 5/360 وانظر صحيح ابن ماجه 2/ 329 وصحيح الترمذي 3/ 163"}]}],"extraReferences":[]},{"id":25,"title":"الأذكار بعد السلام من الصلاة","url":"https://www.imadislam.com/hisnulmuslim/025.htm","entries":[{"number":66,"text":"\" أستغفر الله \" ثلاثاً ..\" اللهم أنت السلام ، ومنك السلام ، تباركت يا ذا الجلال والإكرام\"[1].","key":"25-0","references":[{"number":"1","text":"مسلم1/ 414"}]},{"number":67,"text":"\" لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ وَلَا مُعْطِيَ لِمَا مَنَعْتَ وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ \"[2].","key":"25-1","references":[{"number":"2","text":"البخاري 1 /255 ومسلم 1 / 414"}]},{"number":68,"text":"\"لا إله إلا الله وحده لا شريك له،له الملك وله الحمد وهو على كل شئ قدير،لا حول ولا قوة إلا بالله،لا إله إلا الله،ولا نعبد إلا إياه ، له النعمة وله الفضل ،وله الثناء الحسن،لا إله إلا الله مخلصين له الدين ولو كره الكافرون\"[3] .","key":"25-2","references":[{"number":"3","text":"مسلم 1/ 415"}]},{"number":69,"text":"\" سبحان الله ، والحمد لله ، والله أكبر ( ثلاثاً وثلاثين ) لا إله إلا الله وحده لا شريك له ، له الملك وله الحمد وهو على كل شيء قدير \"[4]","key":"25-3","references":[{"number":"4","text":"مسلم 1/ 418من قال ذلك دبر كل صلاة غفرت خطاياه وإن كانت مثل زبد البحر مسلم 1/ 418"}]},{"number":70,"text":"بسم الله الرحمن الرحيم{ قُلْ هُوَ اللَّهُ أَحَدٌ*اللَّهُ الصَّمَدُ*لَمْ يَلِدْ وَلَمْ يُولَدْ * وَلَمْ يَكُن لَّهُ كُفُواً أَحَدٌ} بسم الله الرحمن الرحيم {قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ * مِن شَرِّ مَا خَلَقَ *وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ * وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ * وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ } بسم الله الرحمن الرحيم{ قُلْ أَعُوذُ بِرَبِّ النَّاسِ * مَلِكِ النَّاسِ * إِلَهِ النَّاسِ *مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ * الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ * مِنَ الْجِنَّةِ وَالنَّاسِ }بعد كل صلاة مرة واحدة , وبعد صلاة المغرب والفجر ثلاث مرات [5]","key":"25-4","references":[{"number":"5","text":"أبو داود2 /86 والنسائي 3/ 68 وانظر صحيح الترمذي 2/8 والسور الثلاث يقال لها المعوذات وانظر فتح الباري 9 / 62"}]},{"number":71,"text":"{ اللّهُ لاَ إِلَـهَ إِلاَّ هُوَ الْحَيُّ الْقَيُّومُ لاَ تَأْخُذُهُ سِنَةٌ وَلاَ نَوْمٌ لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الأَرْضِ مَن ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلاَّ بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلاَ يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلاَّ بِمَا شَاء وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالأَرْضَ وَلاَ يَؤُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ }عقب كل صلاة [6]","key":"25-5","references":[{"number":"6","text":"من قرأها دبر كل صلاة لم يمنعه من دخول الجنة إلا أن يموت . والنسائي في عمل اليوم والليلة برقم 100 ، وابن السني برقم 121 وصححه الجامع 5/339 وسلسلة الأحاديث الصحيحة 2/697 برقم 972"}]},{"number":72,"text":"\" لا إله إلا الله وحده لا شريك له ، له الملك وله الحمد ، يحيي ويميت وهو على كل شئ قدير \" عشر مرات بعد صلاة المغرب والصبح [7] .","key":"25-6","references":[{"number":"7","text":"رواه الترمذي 5/515 وأحمد 4/ 227 وانظر تخريجه في زاد المعاد 1/300"}]},{"number":73,"text":"\" اللهم إني أسألك علماً نافعاً ، ورزقاً طيباً ، وعملاً متقبلاً \"بعد السلام من صلاة الفجر [8] .","key":"25-7","references":[{"number":"8","text":"ابن ماجه وغيره وانظر صحيح ابن ماجة1/ 152 ومجمع الزوائد 10/111"}]}],"extraReferences":[]},{"id":26,"title":"دعاء صلاة الاستخارة","url":"https://www.imadislam.com/hisnulmuslim/026.htm","entries":[{"number":74,"text":"قال جابر بن عبد الله رضي الله عنهما : كان رسول الله صلى الله عليه وسلم ، يُعلمنا الاستخارة في الأمور كلها كما يعلمُنا السورة من القرآن ، يقول : إذا هم أحدكم بالأمر فليركع ركعتين من غير الفريضة ، ثم ليقل :\" اللهم إني أستخيرك بعلمك ، وأستقدرك بقدرتك ، وأسألك من فضلك العظيم فإنك تقدِرُ ولا أقدِرُ ، وتعلم ولا أعلم ، وأنت علام الغيوب ، اللهم إن كنت تعلم أن هذا الأمر -يسمي حاجته - خير لي في ديني ومعاشي وعاقبة أمري - أو قال : عاجلة وآجله - فاقدره لي ويسره لي ، ثم بارك لي فيه ، وإن كنت تعلم أن هذا الأمر شر لي في ديني ومعاشي وعاقبة أمري - أو قال : عاجله وآجله - فاصرفه عني واصرفني عنه ، واقدر لي الخير حيث كان ، ثم ارضني به \"[1].\nوما ندم من استخار الخالق ، وشاور المخلوقين المؤمنين وتثبت في أمره ، فقد قال سبحانه{ وَشَاوِرْهُمْ فِي الأَمْرِ فَإِذَا عَزَمْتَ فَتَوَكَّلْ عَلَى اللّهِ}[2]","key":"26-0","references":[{"number":"1","text":"البخاري7/ 162"},{"number":"2","text":"سورة آل عمران ، آية : 159"}]}],"extraReferences":[]},{"id":27,"title":"أذكار الصباح والمساء","url":"https://www.imadislam.com/hisnulmuslim/027.htm","entries":[{"number":null,"text":"الحمد لله وحده ، والصلاة والسلام على من لا نبي بعده[1]","key":"27-0","references":[{"number":"1","text":"عن أنس يرفعه \" لأن أقعد مع قوم يذكرون الله تعالى من صلاة الغداة حتى تطلع الشمس أحب إلي من أن أعتق أربعة من ولد إسماعيل ، ولأن أقعد مع قوم يذكرون الله من صلاة العصر إلى أن تغرب الشمس أحب إلي من أن أعتق أربعة \" أبو داود برقم 3667، وحسنه الألباني ، صحيح أبو داود 2/ 698"}]},{"number":75,"text":"أعوذ بالله من الشيطان الرجيم { اللّهُ لاَ إِلَـهَ إِلاَّ هُوَ الْحَيُّ الْقَيُّومُ لاَ تَأْخُذُهُ سِنَةٌ وَلاَ نَوْمٌ لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الأَرْضِ مَن ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلاَّ بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلاَ يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلاَّ بِمَا شَاء وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالأَرْضَ وَلاَ يَؤُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ }[2]","key":"27-1","references":[{"number":"2","text":"سورة البقرة ، آية 255 من قالها حين يمسي أجير منهم حتى يصبح أخرجه الحاكم 1/ 562وصححه الألباني في صحيح الترغيب والترهيب 1/ 273 وعزاه إلى النسائي والطبراني وقال : وإسناد الطبراني جيد"}]},{"number":76,"text":"بسم الله الرحمن الرحيم{ قُلْ هُوَ اللَّهُ أَحَدٌ*اللَّهُ الصَّمَدُ*لَمْ يَلِدْ وَلَمْ يُولَدْ * وَلَمْ يَكُن لَّهُ كُفُواً أَحَدٌ} بسم الله الرحمن الرحيم {قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ * مِن شَرِّ مَا خَلَقَ *وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ * وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ * وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ } بسم الله الرحمن الرحيم{ قُلْ أَعُوذُ بِرَبِّ النَّاسِ * مَلِكِ النَّاسِ * إِلَهِ النَّاسِ *مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ * الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ * مِنَ الْجِنَّةِ وَالنَّاسِ }(ثلاث مرات )[3]","key":"27-2","references":[{"number":"3","text":"من قالها ثلاث مرات حين يصبح وحين يمسي كفته من كل شيء . أبو داود 4/ 322 والترمذي 5/ 567وانظر صحيح الترمذي 3/ 182"}]},{"number":77,"text":"\" أصبحنا وأصبح الملك لله[4]، والحمد لله، لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، ربِّ أسألك خير ما في هذا اليوم وخير ما بعده[5] وأعوذ بك من شر ما في هذا اليوم وشر ما بعده ربِّ أعوذ بك من الكسل وسوء الكبر، ربَّ أعوذ بك من عذابٍ في النار وعذاب في القبر\"[6] وإذا أمسي قال ذلك أيضا : \" أمسينا وأمسي الملك لله \".","key":"27-3","references":[{"number":"4","text":"وإذا أمسى قال : أمسينا وأمسى الملك لله"},{"number":"5","text":"وإذا أمسى قال : ربِّ أسألك خير ما في هذه الليلة وخير ما بعدها وأعوذ بك من شر ما في هذه الليلة وشر ما بعدها"},{"number":"6","text":"مسلم 4/ 2088"}]},{"number":78,"text":"\"اللهم بك أصبحنا وبك أمسينا[7] وبك نحيا وبك نموت وإليك النشور\"[8] وإذا أمسي فليقل : \" اللهم بك أمسينا، وبك أصبحنا، وبك نحيا وبك نموت، وإليك المصير \".","key":"27-4","references":[{"number":"7","text":"وإذا أمسى قال: \"اللهم بك أمسينا وبك أصبحنا وبك نحيا وبك نموت وإليك المصير\"."},{"number":"8","text":"الترمذي 5/ 466 وانظر صحيح الترمذي 3/ 142"}]},{"number":79,"text":"\"اللهم أنت ربي لا إله إلا أنت خَلَقتني وأنا عَبْدُك وأنا على عهدك ووعدك ما استطعت أعوذ بك من شر ما صنعت أبوء[9] لك بنعمتك علي وأبوء بذنبي فاغفر لي فإنه لا يغفر الذنوب إلا أنت\"[10]","key":"27-5","references":[{"number":"9","text":"أقر وأعترف"},{"number":"10","text":"من قالها موقناً بها حين يمسي فمات من ليلته دخل الجنة ، وكذلك إذا أصبح أخرجه البخاري 7/150"}]},{"number":80,"text":"اللهم إني أصبحت [11] أشهدك وأشهد حملة عرشك ، وملائكتك وجميع خلقك ، أنك أنت الله لا إله إلا أنت وحدك لا شريك لك ، وأن محمداً عبدك ورسولك\" ( أربع مرات )[12]","key":"27-6","references":[{"number":"11","text":"وإذا أمسى قال : اللهم إني أمسيت"},{"number":"12","text":"من قالها حين يصبح وحين يمسي أربع مرات أعتقه الله من النار . أخرجه أبو داود 4/ 317 والبخاري في الأدب المفرد برقم 1201 والنسائي في عمل اليوم والليلة برقم 9، وابن السني برقم 70 وحسن سماحة الشيخ ابن باز إسناد النسائي وأبي داود في تحفة الأخيار ص 23"}]},{"number":81,"text":"اللهم ما أصبح بي [13]من نعمة أو بأحد من خلقك فمنك وحدك لا شريك لك ، فلك الحمد ولك الشكر \"[14]","key":"27-7","references":[{"number":"13","text":"وإذا أمسى قال : اللهم ما أمسى بي"},{"number":"14","text":"من قالها حين يصبح فقد أدي شكر يومه ، ومن قالها حين يمسى فقد أدى شكر ليلته . أخرجه أبو داود 4/318 ، والنسائي في عمل اليوم والليلة برقم 7وابن السني برقم 41 وابن حبان (( موارد)) رقم 2361وحسن ابن باز إسناده في تحفة الأخيار ص24."}]},{"number":82,"text":"\"اللهم عافني في بَدَني، اللهم عافني في سمعي، اللهم عافني في بصري، لا إله إلا أنت .اللهم إني أعوذ بك من الكفر، والفقر، اللهم إني أعوذ بك من عذاب القبر لا إله إلا أنت\" (ثلاث مرات)[15].","key":"27-8","references":[{"number":"15","text":"أبو داود 4/ 324، وأحمد 5/ 42 والنسائي في عمل اليوم والليلة برقم 22وابن السني برقم 69والبخاري في الأدب المفرد وحسن العلامة ابن باز في تحفة الأخيار ص26"}]},{"number":83,"text":"\"حسبي الله لا إله إلا هو عليه توكلت وهو رب العرش العظيم \"(سبع مرات )[16]","key":"27-9","references":[{"number":"16","text":"من قالها حين يصبح ويمسي سبع مرات كفاه الله ما أهمه من أمر الدنيا والآخرة .أخرجه ابن السني برقم 71مرفوعاً وأبو موقوف 4/321،وصحح إسناده شعيب وعبد القادر الأرناؤوط . انظر زاد المعاد 2/ 376"}]},{"number":84,"text":"\"اللهم إني أسألك العفو والعافية في الدنيا والآخرة، اللهم إني أسألك العفو والعافية في ديني ودنياي وأهلي ومالي،اللهم استر عوراتي وآمن روعاتي، اللهم احفظني من بين يديَّ ومن خلفي وعن يميني وعن شمالي ومن فوقي وأعوذ بعظمتك أن أغتال من تحتي\"[17].","key":"27-10","references":[{"number":"17","text":"أبو داود وابن ماجه وانظر صحيح ابن ماجه 2/332"}]},{"number":85,"text":"\"اللهم عَالِمَ الغيب والشَّهادة، فاطر السموات والأرض، رب كل شيء ومليكه، أشهد أن لا إله إلا أنت أعوذ بك من شر نفسي ومن شر الشيطان وشركه وأن اقترف على نفسي سوءًا أو أجُره إلى مسلم\"[18].","key":"27-11","references":[{"number":"18","text":"الترمذي وأبو داود .انظر :صحيح الترمذي3/ 142"}]},{"number":86,"text":"\" بسم الله الذي لا يضرُّ مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم\"[19] ( ثلاث مرات)","key":"27-12","references":[{"number":"19","text":"من قالها ثلاثاً إذا أصبح وثلاثاً إذا أمسى لم يضره شيء أخرجه أبو داود 4/ 323 والترمذي 5/ 465 وابن ماجه وأحمد . انظر : صحيح ابن ماجه 2/332 وحسن إسناده العلامة ابن باز في تحفة الأخيار ص39"}]},{"number":87,"text":"رضيت بالله رباً ، وبالإسلام ديناً وبمحمد صلى الله عليه وسلم نبياً \" (ثلاث مرات) [20]","key":"27-13","references":[{"number":"20","text":"من قالها ثلاثاً حين يصبح وحين يمسي كان حقاً على الله أن يرضيه يوم القيامة . أحمد 4/ 337 والنسائي في عمل اليوم والليلة برقم 4 وابن السني برقم 68 وأبو داود 4/418 والترمذي 5/465 وحسنه ابن باز في تحفة الأخيار ص 39"}]},{"number":88,"text":"\"يا حي يا قيوم برحمتك أستغيث أصلح لي شأني كُله ولا تَكِلْني إلى نفسي طرفة عين\"[21].","key":"27-14","references":[{"number":"21","text":"الحاكم وصححه ووافقه الذهبي 1/ 545 وانظر صحيح الترغيب والترهيب 1/273"}]},{"number":89,"text":"أصبحنا وأصبح الملك لله رب العالمين[22] ، اللهم إني أسألك خير هذا اليوم[23] : فتحه، ونصره ،ونوره ،وبركته، وهداه، وأعوذ بك من شر ما فيه وشر ما بعده\"[24]","key":"27-15","references":[{"number":"22","text":"وإذا أمسى قال: أمسينا وأمسى الملك لله رب العالمين"},{"number":"23","text":"وإذا أمسى قال: اللهم إني أسألك خير هذه الليلة فتحها ونصرها ونورها وبركتها وهداها وأعوذ بك من شر ما فيها وشر ما بعدها"},{"number":"24","text":"أبو داود 4/ 322 وحسن إسناده شعيب وعبد القادر الأرناؤوط في تحقيق زاد المعاد 2/ 273"}]},{"number":90,"text":"\"أصبحنا على فطرة الإسلام[25] وعلى كلمة الإخلاص، وعلى دين نبيَّنا محمد صلى الله عليه وسلم وعلى ملَّة أبينا إبراهيم حنيفاً مسلماً وما كان من المشركين\"[26].","key":"27-16","references":[{"number":"25","text":"وإذا أمسى قال: أمسينا على فطرة الإسلام"},{"number":"26","text":"أحمد 3/ 406و 407 وابن السني في عمل اليوم والليلة برقم 34 وانظر : صحيح الجامع 4/ 209."}]},{"number":91,"text":"من قال :\"سبحان الله وبحمده\"(مائة مرة )[27].","key":"27-17","references":[{"number":"27","text":"من قالها مائة مرة حين يصبح وحين يمسي لم يأت أحد يوم القيامة بأفضل مما جاء به إلا أحد قال مثل ما قال أو زاد رواه مسلم4 / 2071"}]},{"number":92,"text":"\"لا إله إلا الله وحده لا شريك له ،له الملك وله الحمد وهو على كل شيء قدير\"( عشر مرات)[28]( أو مرة واحدة عند الكسل)[29]","key":"27-18","references":[{"number":"28","text":"النسائي في عمل اليوم والليلة برقم 24 وانظر :صحيح الترغيب والترهيب 1/272 ،وتحفة الأخيار لابن باز ص44وانظر فضلها في ص146 ،حديث رقم 255"},{"number":"29","text":"أبو داود 4/319 وابن ماجه وأحمد 4/60 وانظر :صحيح الترغيب والترهيب 1/270 ،صحيح أبو داود 3/957 ، وصحيح ابن ماجه 2/331 وزاد المعاد 2/ 377"}]},{"number":93,"text":"\" لا إله إلا الله وحده لا شريك له ،له الملك وله الحمد وهو على كل شيء قدير\"(مائة مرة إذا أصبح )[30]","key":"27-19","references":[{"number":"30","text":"من قالها مائة مرة في يوم كانت له عدل عشر رقاب، وكتب له مائة حسنة ،ومحيت عنه مائة سيئة ، وكانت حرزاً من الشيطان يومه ذلك حتى يمسي ،ولم يأت أحد بأفضل مما جاء به إلا أحد عمل أكثر من ذلك . البخاري 4/95،ومسلم 4/2071"}]},{"number":94,"text":"\"سبحان الله وبحمده عدد خلقهِ ورِضَا نفسِهِ وزِنُة عَرشِهِ ومِداد كلماته\"( ثلاث مرات إذا أصبح )[31]","key":"27-20","references":[{"number":"31","text":"مسلم 4/2090"}]},{"number":95,"text":"\" اللهم إني أسألك علماً نافعاً ، ورزقاً طيباً ، وعملاً متقبلاً \" ( إذا أصبح ) [32]","key":"27-21","references":[{"number":"32","text":"أخرجه ابن السني في عمل اليوم والليلة برقم 54وابن ماجه برقم 925وحسن إسناده عبد القادر وشعيب الأرناؤوط في تحقيق زاد المعاد 2/375"}]},{"number":96,"text":"\"أستغفر الله وأتوب إليه \" (مائة مرة في اليوم )[33]","key":"27-22","references":[{"number":"33","text":"البخاري مع الفتح 11/ 101 ، ومسلم 4/ 2075"}]},{"number":97,"text":"\"أعوذ بكلمات الله التامات من شر ما خلق\" ( ثلاث مرات إذا أمسى)[34].","key":"27-23","references":[{"number":"34","text":"من قالها حين يمسي ثلاث مرات لم تضره حمة تلك الليلة أخرجه أحمد 2/290 والنسائي في عمل اليوم والليلة برقم 590 وابن السني برقم 68وانظر : صحيح الترمذي 3/187، وصحيح ابن ماجه 2/266 وتحفة الأخيار ص45."}]},{"number":98,"text":"\" اللهم صل وسلم على نبينا محمد \" (عشر مرات )[35]","key":"27-24","references":[{"number":"35","text":"من صلى علي حين يُصبح عشراً ، وحين يُمسي عشراً أدركتهُ شفاعتي يوم القيامة\"... رواه الطبراني بإسنادين أحدهما جيد ، انظر الزائد 10/ 120 وصحيح الترغيب والترهيب 1/273"}]}],"extraReferences":[]},{"id":28,"title":"أذكار النوم","url":"https://www.imadislam.com/hisnulmuslim/028.htm","entries":[{"number":99,"text":"\"يجمع كفيه ثم ينفث فيهما فيقرأ:بسم الله الرحمن الرحيم{ قُلْ هُوَ اللَّهُ أَحَدٌ*اللَّهُ الصَّمَدُ*لَمْ يَلِدْ وَلَمْ يُولَدْ*وَلَمْ يَكُن لَّهُ كُفُواً أَحَدٌ} بسم الله الرحمن الرحيم{قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ*مِن شَرِّ مَا خَلَقَ*وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ*وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ * وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ } بسم الله الرحمن الرحيم{ قُلْ أَعُوذُ بِرَبِّ النَّاسِ * مَلِكِ النَّاسِ * إِلَهِ النَّاسِ *مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ * الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ * مِنَ الْجِنَّةِ وَالنَّاسِ }ثم يمسح بهما ما استطاع من جسده يبدأبهما على رأسه ووجهه وما أقبل من جسده\" ( يفعل ذلك ثلاث مرات )[1]","key":"28-0","references":[{"number":"1","text":"البخاري مع الفتح 9/62ومسلم 4/1723"}]},{"number":100,"text":"{ اللّهُ لاَ إِلَـهَ إِلاَّ هُوَ الْحَيُّ الْقَيُّومُ لاَ تَأْخُذُهُ سِنَةٌ وَلاَ نَوْمٌ لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الأَرْضِ مَن ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلاَّ بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلاَ يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلاَّ بِمَا شَاء وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالأَرْضَ وَلاَ يَؤُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ }[2]","key":"28-1","references":[{"number":"2","text":"من قرأها إذا أوى إلى فراشه فإنه لن يزال عليه من الله حافظ ولا يقربه شيطان حتى يصبح البخاري مع الفتح 4/487"}]},{"number":101,"text":"{آمَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِن رَّبِّهِ وَالْمُؤْمِنُونَ كُلٌّ آمَنَ بِاللّهِ وَمَلآئِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لاَ نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِ وَقَالُواْ سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ * لاَ يُكَلِّفُ اللّهُ نَفْساً إِلاَّ وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ رَبَّنَا لاَ تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا رَبَّنَا وَلاَ تَحْمِلْ عَلَيْنَا إِصْراً كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا رَبَّنَا وَلاَ تُحَمِّلْنَا مَا لاَ طَاقَةَ لَنَا بِهِ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا أَنتَ مَوْلاَنَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ}[3]","key":"28-2","references":[{"number":"3","text":"من قرأها في ليلة كفتاه، البخاري مع الفتح 9/ 94 ومسلم 1/ 554 ، والآيتان من سورة البقرة ، 285 — 286"}]},{"number":102,"text":"باسمك[4] ربي وضعت جنبي وبك أرفعه إن أمسكت نفسي فارحمها، وإن أرسلتها فاحفظها بما تحفظ به عبادك الصالحين\"[5].","key":"28-3","references":[{"number":"4","text":"\"إذا قام أحدكم من فراشه ثم رجع إليه فلينفض بصنفة إزاره ثلاث مرات وليسم الله فإنه لا يدري ماذا خلفه عليه بعده وإذا اضطجع فليقل ... \" الحديث"},{"number":"5","text":"البخاري 11/ 126 .ومسلم 4/ 2084"}]},{"number":103,"text":"\"اللهم خَلَقْتَ نفسي وأنت توفَّاها لك مماتها ومَحْياها، إن أحييتها فاحفظها وإن أمتها فاغفر لها، اللهم إني أسألك العافية\"[6].","key":"28-4","references":[{"number":"6","text":"رواه مسلم4/ 2083وأحمد بلفظه 2/79"}]},{"number":104,"text":"\"اللهم قني[7] عذابك يوم تبعث عبادك\"( ثلاث مرات )[8].","key":"28-5","references":[{"number":"7","text":"كان الرسول صلى الله عليه وسلم إذا أراد أن يرقد وضع يده اليمنى تحت خده ثم يقول ..........\" الحديث"},{"number":"8","text":"أبو داود بلفظه 4/311 وانظر صحيح الترمذي3/ 143"}]},{"number":105,"text":"\" باسمِكَ اللهم أموت وأحيا \"[9].","key":"28-6","references":[{"number":"9","text":"البخاري مع الفتح 11/113 ومسلم 4/ 2083"}]},{"number":106,"text":"\" سبحان الله ( ثلاثاً وثلاثين ) والحمد لله ( ثلاثاً وثلاثين )والله أكبر(أربعاً وثلاثين )[10]","key":"28-7","references":[{"number":"10","text":"من قال ذلك عندما يأوي إلى فراشه كان خيراً له من خادم البخاري مع الفتح 7/71 ومسلم 4/ 2091"}]},{"number":107,"text":"\"اللهم ربَّ السموات السبع،ورب العرش العظيم،ربنا ورب كل شيء، فالق الحب والنوى، ومُنزل التوراة والإنجيل والفرقان، أعوذ بك من شر كل شيء أنت آخذٌ بناصيته،اللهم أنت الأول فليس قبلك شيء،وأنت الآخر فليس بعدك شيء، وأنت الظاهر فليس فوقك شيء، وأنت الباطن فليس دونك شيء، اقض عنا الدَّيْنَ واغننا من الفقر\"[11].","key":"28-8","references":[{"number":"11","text":"مسلم 4/ 2084"}]},{"number":108,"text":"\"الحمد لله الذي أطعمنا وسقانا وكفانا وآوانا فكم ممن لا كافي له ولا مؤوي\"[12].","key":"28-9","references":[{"number":"12","text":"مسلم 4/ 2085"}]},{"number":109,"text":"\"اللهم عالم الغيب والشهادة، فاطر السموات والأرض، رب كل شيء ومليكه أشهد أن لا إله إلا أنت أعوذ بك من شر نفسي، ومن شر الشيطان وشركه وأن أقترف على نفسي سوءًا أو أجرَّه إلى مسلم\"[13].","key":"28-10","references":[{"number":"13","text":"أبو داود 4/ 317 وانظر صحيح سنن الترمذي3/ 142"}]},{"number":110,"text":"\" يقرأ {ألم } تنزيل السجدة، و{تبارك الذي بيده الملك}\"[14].","key":"28-11","references":[{"number":"14","text":"الترمذي والنسائي وانظر صحيح الجامع4/ 255"}]},{"number":111,"text":"\" اللهم [15]أسلمت نفسي إليك، وفوضت أمري إليك وألجأت ظهري إليك رهبةً ورغبةً إليك، لا ملجأ ولا منجا منك إلا إليك، آمنت بكتابك الذي أنزلت وبنبيك الذي أرسلت\"[16]","key":"28-12","references":[{"number":"15","text":"\"إذا أخذت مضجعك فتوضأ وضوءك للصلاة ثم اضطجع على شقك الأيمن، وقل:....\" الحديث"},{"number":"16","text":"قال صلى الله عليه وسلم لمن قال ذلك : \"فإن متَّ،متَّ على الفطرة \" البخاري مع الفتح 11/113 ومسلم 4/ 2081"}]}],"extraReferences":[]},{"id":29,"title":"الدعاء إذا تقلب ليلاً","url":"https://www.imadislam.com/hisnulmuslim/029.htm","entries":[{"number":112,"text":"\" لا إله إلا الله الواحد القهار، ربُّ السموات والأرض وما بينهما العزيز الغفار \"[1].","key":"29-0","references":[{"number":"1","text":"يقول ذلك إذا تقلب من جنب إلى جنب في الليل . أخرجه الحاكم وصححه ووفقه الذهبي 1/ 540 والنسائي في اليوم والليلة وابن السني وانظر صحيح الجامع 4/213"}]}],"extraReferences":[]},{"id":30,"title":"دعاء القلق والفزع في النوم ومن بلي بالوحشة","url":"https://www.imadislam.com/hisnulmuslim/030.htm","entries":[{"number":113,"text":"\" أعوذ بكلمات الله التَّامَّة من غضبه وعقابه، وشر عباده، ومن همزات الشياطين وأنْ يحضرون \"[1].","key":"30-0","references":[{"number":"1","text":"أبو داود 4/12 نظر صحيح الترمذي3/ 171"}]}],"extraReferences":[]},{"id":31,"title":"ما يفعل من رأى الرؤيا أو الحلم","url":"https://www.imadislam.com/hisnulmuslim/031.htm","entries":[{"number":114,"text":"\" ينفث عن يساره \" (ثلاثاً)[1].\n\" يستعيذ بالله من الشيطان ومن شر ما رأى \" (ثلاث مرات)[2].\n\" لا يحدث بها أحدا ً \"[3].\n\" يتحول عن جنبه الذي كان عليه \"[4].","key":"31-0","references":[{"number":"1","text":"مسلم4/1772"},{"number":"2","text":"مسلم4/1772- 1773"},{"number":"3","text":"مسلم4/1772"},{"number":"4","text":"مسلم4/1773"}]},{"number":115,"text":"\" يقوم يصلي إن أراد ذلك \"[5].","key":"31-1","references":[{"number":"5","text":"مسلم4/1773"}]}],"extraReferences":[]},{"id":32,"title":"دعاء قنوت الوتر","url":"https://www.imadislam.com/hisnulmuslim/032.htm","entries":[{"number":116,"text":"\" اللهم اهدني فيمن هديت ، وعافني فيمن عافيت ، وتولني فيمن توليت ، وبارك لي فيما أعطيت ، وقني شر ما قضيت ، فإنك تقضي ولا يقضى عليك ، إنه لا يذل من واليت ،[ ولا يعز من عاديت ] تباركت ربنا وتعاليت \"[1]","key":"32-0","references":[{"number":"1","text":"أخرجه أصحاب السنن الأربعة وأحمد والدرامي والحاكم والبيهقي وما بين المعكوفين للبيهقي وانظر صحيح الترمذي 1/144وصحيح ابن ماجه 1/194 وإرواء الغليل للألباني 2/172"}]},{"number":117,"text":"\" اللهم إني أعوذ برضاك من سخطك وأعوذ بمعافاتك من عقوبتك ، وأعوذ بك منك لا أحصي ثناء عليك ، أنت كما أثنيت على نفسك \"[2]","key":"32-1","references":[{"number":"2","text":"أخرجه أصحاب السنن الأربعة وأحمد. انظر صحيح الترمذي 3/180وصحيح ابن ماجه 1/194 والإرواء 2/175"}]},{"number":118,"text":"\" اللهم إياك نعبد ، ولك نُصلي ونسجد ، وإليك نسعى ونحفدُ ، نرجُو رحمتك ، ونخشى عذابك ، إن عذابك بالكافرين ملحق ، اللهم إنا نستعينك ، ونستغفرك ، ونثني عليك الخير ، ولا نكفرك ، ونؤمن بك ونخضع لك ، ونخلع من يكفرك \"[3].","key":"32-2","references":[{"number":"3","text":"أخرجه البيهقي في السنن الكبرى وصحح إسناده 2/211 وقال الشيخ الألباني في إرواء الغليل وهذا إسناد صحيح 2/170 .وهو موقوف على عمر ."}]}],"extraReferences":[]},{"id":33,"title":"الذكر عقب السلام من الوتر","url":"https://www.imadislam.com/hisnulmuslim/033.htm","entries":[{"number":119,"text":"كان رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يقرأ في الوتر :( سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى ) و ( وَقُلْ يَا أَيُّهَا الْكَافِرُونَ ) و ( وَقُلْ هُوَ اللَّهُ أَحَدٌ). فإذا سلم قال \" سبحان الملك القدوس [رب الملائكة والروح ] \" ثلاث مرات والثالثة يجهر بها ويمد بها صوته \"[1].","key":"33-0","references":[{"number":"1","text":"رواه النسائي 3/244 والدار قطني وغيرهما وما بين المعكوفين زيادة للدار قطني 2/31 وإسناده صحيح .انظر زاد المعاد بتحقيق شعيب الأرناؤوط وعبد القادر الأرناؤوط 1/337"}]}],"extraReferences":[]},{"id":34,"title":"دعاء الهم والحزن","url":"https://www.imadislam.com/hisnulmuslim/034.htm","entries":[{"number":120,"text":"\" اللهم إني عبدك ابن عبدك ابن أمتك ناصيتي بيدك،ماضِ في حكمك ، عدل في قضاؤك ،أسألك بكل اسم هو لك سميت به نفسك أو أنزلته في كتابك ، أو علمته أحداً من خلقك أو استأثرت به في علم الغيب عندك أن تجعل القرآن ربيع قلبي ، ونور صدري ،وجلاء حزني وذهاب همي \"[1]","key":"34-0","references":[{"number":"1","text":"أحمد 1/391وصححه الألباني"}]},{"number":121,"text":"\" اللهم إني أعوذ بك من الهم والحزن ، والعجز والكسل والبخل والجبن ، وضلع الدين وغلبة الرجال \"[2].","key":"34-1","references":[{"number":"2","text":"البخاري 7/158 كان رسول الله صلى الله عليه وسلم يكثر من هذا الدعاء."}]}],"extraReferences":[]},{"id":35,"title":"دعاء الكرب","url":"https://www.imadislam.com/hisnulmuslim/035.htm","entries":[{"number":122,"text":"\" لاَ إِلَهَ إِلاَّ اللَّهُ الْعَظِيمُ الْحَلِيمُ، لاَ إِلَهَ إِلاَّ اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ، لاَ إِلَهَ إِلاَّ اللَّهُ رَبُّ السَّمَوَاتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيمِ\"[1] .","key":"35-0","references":[{"number":"1","text":"البخاري 7/154ومسلم 4/ 2092"}]},{"number":123,"text":"\" اللهم رحمتك أرجو فلا تكلني إلى نفسي طرفة عين ِ وأصلح لي شأني كله لا إله إلا أنت \"[2].","key":"35-1","references":[{"number":"2","text":"أبو داود 4/324 وأحمد 5/42 وحسنه الألباني في صحيح أبو داود 3/ 959"}]},{"number":124,"text":"\" لا إله إلا أنت سبحانك إني كنت من الظالمين \"[3]","key":"35-2","references":[{"number":"3","text":"الترمذي 5/529 والحاكم وصححه ووفقه الذهبي 1/505 وانظر صحيح الترمذي3/ 168"}]},{"number":125,"text":"\" الله الله ربي لا أشرك به شيئاً \"[4]","key":"35-3","references":[{"number":"4","text":"أخرجه أبو داود 2/87 وانظر صحيح ابن ماجه 2/335"}]}],"extraReferences":[]},{"id":36,"title":"دعاء لقاء العدو وذي السلطان","url":"https://www.imadislam.com/hisnulmuslim/036.htm","entries":[{"number":126,"text":"\"اللهم إنا نجعلك في نحورهم ونعوذ بك من شرورهم \"[1]","key":"36-0","references":[{"number":"1","text":"أبو داود 2/89 وصححه الحاكم ووافقه الذهبي 2/142"}]},{"number":127,"text":"\"اللهم أنت عضُدي وأنت نصيري ، بك أحولُ ،وبك أصولُ ، وبك أُقاتلُ\"[2].","key":"36-1","references":[{"number":"2","text":"أبو داود 3/42 والترمذي 5/572 ،وانظر صحيح الترمذي3/183"}]},{"number":128,"text":"\"حسبنا الله ونعم الوكيل \" [3]","key":"36-2","references":[{"number":"3","text":"البخاري 5/172"}]}],"extraReferences":[]},{"id":37,"title":"دعاء من خاف ظلم السلطان","url":"https://www.imadislam.com/hisnulmuslim/037.htm","entries":[{"number":129,"text":"\" اللهم رب السموات السبع ،ورب العرش العظيم ،كن لي جاراً من فلان بن فلان ، وأحزابه من خلائقك ؛ أن يفرط على أحد منهم أو يطغى ، عز جارك ،وجل ثناؤك ،ولا إله إلا أنت \"[1]","key":"37-0","references":[{"number":"1","text":"البخاري في الأدب المفرد برقم 707 وصححه الألباني وفي صحيح الأدب المفرد برقم 545"}]},{"number":130,"text":"\" الله أكبر، الله أعز من خلقه جميعاً ، الله أعز مما أخاف وأحذر ،أعوذ بالله الذي لا إله إلا هو ، الممسك السموات السبع أن يقعن على الأرض إلا بإذنه ،من شر عبدك فلان ،وجنوده وأتباعه وأشياعه ، من الجن والأنس ، اللهم كن لي جاراً من شرهم ، جل ثناؤك وعز جارك ، وتبارك اسمك ، ولا إله غيرك \" (ثلاث مرات )[2]","key":"37-1","references":[{"number":"2","text":"البخاري في الأدب المفرد برقم 708 وصححه الألباني وفي صحيح الأدب المفرد برقم 546"}]}],"extraReferences":[]},{"id":38,"title":"الدعاء على العدو","url":"https://www.imadislam.com/hisnulmuslim/038.htm","entries":[{"number":131,"text":"\" اللهم منزل الكتاب ، سريع الحساب ،اهزم الأحزاب ،اللهم اهزمهم وزلزلهم \"[1]","key":"38-0","references":[{"number":"1","text":"مسلم 3/1362"}]}],"extraReferences":[]},{"id":39,"title":"ما يقول من خاف قوماً","url":"https://www.imadislam.com/hisnulmuslim/039.htm","entries":[{"number":132,"text":"\" اللهم اكفنيهم بما شئت \" [1]","key":"39-0","references":[{"number":"1","text":"مسلم 4/2300"}]}],"extraReferences":[]},{"id":40,"title":"دعاء من أصابه شك في الإيمان","url":"https://www.imadislam.com/hisnulmuslim/040.htm","entries":[{"number":133,"text":"\"يستعيذ بالله \" [1]\n\"ينتهي عما شك فيه \"[2]","key":"40-0","references":[{"number":"1","text":"البخاري مع الفتح 6/336 ومسلم 1/120"},{"number":"2","text":"البخاري مع الفتح 6/336 ومسلم 1/120"}]},{"number":134,"text":"يقول\" آمنت بالله ورسله \"[3]","key":"40-1","references":[{"number":"3","text":"مسلم 1/ 119- 120"}]},{"number":135,"text":"يقرأ قوله تعالى{ هُوَ الْأَوَّلُ وَالْآخِرُ وَالظَّاهِرُ وَالْبَاطِنُ وَهُوَ بِكُلِّ شَيْءٍ عَلِيمٌ }\"[4]","key":"40-2","references":[{"number":"4","text":"سورة الحديد ، الآية :3 .أبو داود 4/329 وحسنه الألباني في صحيح أبو داود 3/962"}]}],"extraReferences":[]},{"id":41,"title":"الدعاء قضاء الدين","url":"https://www.imadislam.com/hisnulmuslim/041.htm","entries":[{"number":136,"text":"\" اللهم اكفني بحلالك عن حرامك ، وأغنني بفضلك عمن سواك \"[1]","key":"41-0","references":[{"number":"1","text":"الترمذي 5/560 وانظر صحيح الترمذي3/ 180"}]},{"number":137,"text":"\" اللهم إني أعوذ بك من الهم والحزن ، والعجز والكسل ،والبخل والجبن وضلع الدين وغلبة الرجال\"[2].","key":"41-1","references":[{"number":"2","text":"البخاري7/ 158"}]}],"extraReferences":[]},{"id":42,"title":"دعاء الوسوسة في الصلاة والقراءة","url":"https://www.imadislam.com/hisnulmuslim/042.htm","entries":[{"number":138,"text":"\" أعوذ بالله من الشيطان الرجيم واتفل على يسارك ( ثلاثاً )[1]","key":"42-0","references":[{"number":"1","text":"مسلم 4/1729 من حديث عثمان بن العاص رضي الله عنه وفيه ففعلت ذلك فأذهبه الله عني"}]}],"extraReferences":[]},{"id":43,"title":"دعاء من استصعب عليه أمر","url":"https://www.imadislam.com/hisnulmuslim/043.htm","entries":[{"number":139,"text":"\" اللهم لا سهل إلا ما جعلته سهلاً وأنت تجعل الحزن إذا شئت سهلاً \"[1].","key":"43-0","references":[{"number":"1","text":"رواة ابن حبان في صحيحه برقم 2427 (موارد) وابن السني برقم 351 وقال الحافظ هذا حديث صحيح وصححه عبد القادر الأرناؤوط في تخريج الأذكار للنووي ص106"}]}],"extraReferences":[]},{"id":44,"title":"ما يقول ويفعل من أذنب ذنباً","url":"https://www.imadislam.com/hisnulmuslim/044.htm","entries":[{"number":140,"text":"\" ما من عبدٍ يذنب ذنباً فيحسن الطهور ، ثم يقوم فيصلي ركعتين ، ثم يستغفر الله إلا غفر الله لهُ \" [1]","key":"44-0","references":[{"number":"1","text":"أبو داود 2/86 والترمذي 2/257 وصححه الألباني في صحيح أبي داود 1/ 283"}]}],"extraReferences":[]},{"id":45,"title":"دعاء طرد الشيطان ووساوسه","url":"https://www.imadislam.com/hisnulmuslim/045.htm","entries":[{"number":141,"text":"\" الاستعاذة بالله منه \"[1]","key":"45-0","references":[{"number":"1","text":"أبو داود 1/206 والترمذي وانظر صحيح الترمذي 1/77 وانظر سورة المؤمنون آية 98-99"}]},{"number":142,"text":"\" الأذان \" [2]","key":"45-1","references":[{"number":"2","text":"مسلم 1/ 291 والبخاري 1/151"}]},{"number":143,"text":"\" الأذكار وقراءة القرآن \" [3]","key":"45-2","references":[{"number":"3","text":"\" لاتجعلوا بيوتكم مقابر إن الشيطان ينفر من البيت الذي تقرأ فيه سورة البقرة \" رواه مسلم 1/539 ومما يطرد الشيطان أذكار الصباح والمساء ، والنوم والاستيقاظ ، وأذكار دخول المنزل والخروج منه وأذكار دخول المسجد والخروج منه وغير ذلك من الأذكار المشروعة مثل قراءة آية الكرسي عند النوم ، والآيتين الأخيرتين من سورة البقرة ، ومن قال لا إله إلا الله وحده لا شريك له ،له الملك وله الحمد وهو على كل شيء قدير مائة مرة كانت له حرزاً من الشيطان يومه كله ،وكذا الأذان يطرد الشيطان"}]}],"extraReferences":[]},{"id":46,"title":"الدعاء حينما يقع مالا يرضاه أو غلب على أمره","url":"https://www.imadislam.com/hisnulmuslim/046.htm","entries":[{"number":144,"text":"\" قدر الله وما شاء فعل \"[1]\nإذا غلبك أمر فقل : \" حسبي الله ونعم الوكيل \"[2]","key":"46-0","references":[{"number":"1","text":"\" المؤمن القوي خير وأحب إلى الله من المؤمن الضعف وفي كل خير ،احرص على ما ينفعك واستعن بالله ولا تعجز وإن أصابك شيء فلا تقل لو أني فعلت كذا وكذا ولكن قل قدر الله وما شاء فعل فإن لو تفتح عمل الشيطان \" .مسلم 4/2052."},{"number":"2","text":"انظر تخريج الأذكار للأرناؤوط ص 106."}]}],"extraReferences":[]},{"id":47,"title":"تهنئة المولود له وجوابه","url":"https://www.imadislam.com/hisnulmuslim/047.htm","entries":[{"number":145,"text":"\" بارك الله لك في الموهوب لك ،وشكرت الواهب، وبلغ أشدهُ، ورزقت برهُ \" .ويردُ عليه المهنأ فيقول : \" بارك الله لك وبارك عليك ، وجزاك الله خيراً ، ورزقك الله مثله، وأجزل ثوابك \"[1] .","key":"47-0","references":[{"number":"1","text":"انظر الأذكار للنووي ص349 وصحيح الأذكار للنووي ، لسليم الهلالي 2/713."}]}],"extraReferences":[]},{"id":48,"title":"ما يعوذ به الأولاد","url":"https://www.imadislam.com/hisnulmuslim/048.htm","entries":[{"number":146,"text":"كان رسول الله صلى الله عليه وسلم يعوذ الحسن والحسين \" أعيذكما بكلمات الله التامة ، من كل شيطان وهامة ، ومن كل عينِ لامة \"[1].","key":"48-0","references":[{"number":"1","text":"البخاري 4/119 من حديث ابن عباس رضي الله عنهما"}]}],"extraReferences":[]},{"id":49,"title":"الدعاء للمريض في عيادته","url":"https://www.imadislam.com/hisnulmuslim/049.htm","entries":[{"number":147,"text":"\" لا بأس طهور إن شاء الله \"[1] .","key":"49-0","references":[{"number":"1","text":"البخاري مع الفتح 10/ 118"}]},{"number":148,"text":"\" أسأل الله العظيم رب العرش العظيم أن يشفيك\" (سبع مرات)[2]","key":"49-1","references":[{"number":"2","text":"ما من عبد مسلم يعود مريضاً لم يحضر أجله فيقول: سبع مرات.....\"الحديث إلا عوفي . أخرجه الترمذي وأبو داود وانظر صحيح الترمذي2/ 210 وصحيح الجامع 5/180"}]}],"extraReferences":[]},{"id":50,"title":"فضل عيادة المريض","url":"https://www.imadislam.com/hisnulmuslim/050.htm","entries":[{"number":149,"text":"قال صلى الله عليه وسلم :\" إذا عاد الرجل أخاه المسلم مشى في خرافة الجنة حتى يجلس فإذا جلس غمرته الرحمة ، فإن كان غدوة صلى عليه سبعون ألف ملك حتى يمسي ، وإن كان مساء صلى عليه سبعون ألف ملك حتى يصبح \"[1]","key":"50-0","references":[{"number":"1","text":"رواه الترمذي وابن ماجه وأحمد وانظر صحيح ابن ماجه 1/244 وصحيح الترمذي 1/286 وصححه أيضاً أحمد شاكر"}]}],"extraReferences":[]},{"id":51,"title":"دعاء المريض الذي يئس من حياته","url":"https://www.imadislam.com/hisnulmuslim/051.htm","entries":[{"number":150,"text":"\" اللهم اغفر لي وارحمني والحقني بالرفيق الأعلى\"[1]","key":"51-0","references":[{"number":"1","text":"البخاري 7/10 ومسلم 4/1893"}]},{"number":151,"text":"\" جعل النبي صلى الله عليه وسلم يدخل يديه في الماء فيمسح بهما وجههُ ويقول : لا إله إلا الله إن للموت لسكرات\" [2]","key":"51-1","references":[{"number":"2","text":"البخاري مع الفتح 8/144وفي الحديث السواك"}]},{"number":152,"text":"\" لا إله إلا الله والله أكبر ، لا إله إلا الله وحده ، لا إله إلا الله وحده لا شريك لهُ ، لا إله إلا الله لهُ الملك ولهُ الحمد ، لا إله إلا الله ولا حول ولا قوة إلا بالله\"[3] .","key":"51-2","references":[{"number":"3","text":"أخرجه الترمذي وابن ماجه وصححه الألباني ، وانظر صحيح الترمذي 3/152وصحيح ابن ماجه 2/317"}]}],"extraReferences":[]},{"id":52,"title":"تلقين المحتضر","url":"https://www.imadislam.com/hisnulmuslim/052.htm","entries":[{"number":153,"text":"\" من كان آخر كلامه لا إله إلا الله دخل الجنة \"[1]","key":"52-0","references":[{"number":"1","text":"أبو داود 3/190 وانظر صحيح الجامع 5/432"}]}],"extraReferences":[]},{"id":53,"title":"دعاء من أصيب بمصيبة","url":"https://www.imadislam.com/hisnulmuslim/053.htm","entries":[{"number":154,"text":"\" إنا لله وإنا إليه راجعون اللهم أجرني في مصيبتي وأخلف لي خيراً منها \"[1]","key":"53-0","references":[{"number":"1","text":"مسلم 2/632"}]}],"extraReferences":[]},{"id":54,"title":"الدعاء عند إغماض الميت","url":"https://www.imadislam.com/hisnulmuslim/054.htm","entries":[{"number":155,"text":"\" اللهم اغفر لفلان ( باسمه) ورفع درجته في المهديين، واخلفه في عقبه في الغابرين، واغفر لنا وله يا رب العالمين ،وافسح له في قبره ونور له فيه\"[1]","key":"54-0","references":[{"number":"1","text":"مسلم 2/634"}]}],"extraReferences":[]},{"id":55,"title":"الدعاء للميت في الصلاة عليه","url":"https://www.imadislam.com/hisnulmuslim/055.htm","entries":[{"number":156,"text":"\" اللهم اغفر له وارحمه، وعافه ،واعف عنه ،وأكرم نُزُله ، ووسع مُدخلهُ ، واغسله بالماء والثلج والبرد ، ونقه من الخطايا كما ينقى الثوب الأبيض من الدنس ، وأبدله داراً خيراً من داره ، وأهلاً خيراً من أهله وزوجاً خيراً من زوجه، وأدخله الجنة ،وأعذه من عذاب القبر ( ومن عذاب النار )\"[1]","key":"55-0","references":[{"number":"1","text":"مسلم 2/663"}]},{"number":157,"text":"\" اللهم اغفر لحينا وميتنا ، وشاهدنا وغائبنا ، وصغيرنا وكبيرنا ، وذكرنا وأُنثانا ، اللهم من أحييته منا فأحيه على الإسلام ، ومن توفيته منا فتوفه على الإيمان ، اللهم لا تحرمنا أجره ولا تضلنا بعده\"[2]","key":"55-1","references":[{"number":"2","text":"ابن ماجه 1/480 وأحمد 2/368 وانظر صحيح ابن ماجة1/ 251"}]},{"number":158,"text":"\" اللهم إن فلان بن فلان في ذمتك،وحبل جوارك،فقه من فتنة القبر وعذاب النار،وأنت أهل الوفاء والحق .فاغفر له وارحمهُ إنك أنت الغفور الرحيم\"[3]","key":"55-2","references":[{"number":"3","text":"أخرجه ابن ماجه ، وانظر صحيح ابن ماجة1/ 251ورواه أبو داود 3/211"}]},{"number":159,"text":"\" اللهم عبدك وابن عبدك وابن أمتك احتاج إلى رحمتك ،وأنت غني عن عذابه،إن كان مُحسناً فزده في حسناته، وإن كان مُسيئاً فتجاوز عنه\" [4]","key":"55-3","references":[{"number":"4","text":"أخرجه الحاكم وصححه ووافقه الذهبي 1/359 وانظر أحكام الجنائز للألباني ص125"}]}],"extraReferences":[]},{"id":56,"title":"الدعاء للفرط في الصلاة عليه","url":"https://www.imadislam.com/hisnulmuslim/056.htm","entries":[{"number":160,"text":"\" اللهم أعذه من عذاب القبر \"[1]\nأن قال :\" اللهم اجعله فرطاً وذخراً لوالديه ،وشفيعاً مجاباً .اللهم ثقل به موازينها وأعظم به أجورهما ، وألحقهُ بصالح المؤمنين ، واجعلهُ في كفالة إبراهيم ، وقه برحمتك عذاب الجحيم ، وأبدله داراً خيراً من داره ، وأهلاً خيراً من أهله ، اللهم اغفر لاسلافنا ، وأفراطنا ، ومن سبقنا بالإيمان \" فحسن[2]","key":"56-0","references":[{"number":"1","text":"قال سعيد بن المسيب صليت وراء أبي هريرة على صبي لم يعمل خطيئة قط فسمعته يقول ...\" الحديث .أخرجه مالك في الموطأ 1/288 وابن أبي شيبه في المصنف 3/ 217 والبيهقي 4/9، وصحح إسناده شعيب الأرناؤوط في تحقيقه لشرح السنة للبغوي 5/357."},{"number":"2","text":"انظر : المغني لابن قدامة 3/416 والدروس المهمة لعامة الأمة للشيخ عبد العزيز بن عبد الله بن باز حفظه الله ص15."}]},{"number":161,"text":"\" اللهم اجعله لنا فرطاً ،وسلفاً وأجراً\" [3]","key":"56-1","references":[{"number":"3","text":"كان الحسن يقرأ على الطفل بفاتحة الكتاب ويقول .. \" الحديث أخرجه البغوي في شرح السنة 5/357وعبد الرزاق برقم 6588، وعلقه البخاري في كتاب الجنائز ، 65باب قراءة فاتحة الكتاب على الجنازة 2/113"}]}],"extraReferences":[]},{"id":57,"title":"دعاء التعزية","url":"https://www.imadislam.com/hisnulmuslim/057.htm","entries":[{"number":162,"text":"\" إن لله ما أخذ وله ما أعطى . وكل شيء عنده بأجل مُسمى ...فلتصبر ولتحتسب \"[1]\nوإن قال : \" أعظم الله أجرك ،وأحسن عزاءك وغفر لميتك \" فحسن [2]","key":"57-0","references":[{"number":"1","text":"البخاري 2/80 ومسلم 2/636"},{"number":"2","text":"الأذكار للنووي ص126 ."}]}],"extraReferences":[]},{"id":58,"title":"دعاء عند إدخال الميت القبر","url":"https://www.imadislam.com/hisnulmuslim/058.htm","entries":[{"number":163,"text":"\" بسم الله وعلى سُنة رسول الله \"[1]","key":"58-0","references":[{"number":"1","text":"أبو داود 3/314بسند صحيح وأحمد بلفظ بسم الله وعلى ملة رسول الله وسنده صحيح ."}]}],"extraReferences":[]},{"id":59,"title":"دعاء بعد دفن الميت","url":"https://www.imadislam.com/hisnulmuslim/059.htm","entries":[{"number":164,"text":"\" اللهم اغفر له اللهم ثبته \"[1]","key":"59-0","references":[{"number":"1","text":"كان النبي صلى الله عليه وسلم إذا فرغ من دفن الميت وقف عليه فقال :\" استغفروا لأخيكم وسلوا له التثبيت فإنه الآن يُسأل\" .أبو داود 3/315 والحاكم وصححه ووافقه الذهبي 1/370"}]}],"extraReferences":[]},{"id":60,"title":"دعاء زيارة القبور","url":"https://www.imadislam.com/hisnulmuslim/060.htm","entries":[{"number":165,"text":"\" السلام عليكم أهل الديار ، من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون [ ويرحم الله المُستقدمين منا والمستأخرين ] أسأل الله لنا ولكم العافية [1]","key":"60-0","references":[{"number":"1","text":"سلمم2/671 ،وابن ماجه واللفظ له 1/494 عن بريدة رضي الله عنه ، وما بين المعكوفين من حديث عائشة رضي الله عنها عند مسلم 2/671"}]}],"extraReferences":[]},{"id":61,"title":"دعاء الريح","url":"https://www.imadislam.com/hisnulmuslim/061.htm","entries":[{"number":166,"text":"\" اللهم إني أسألك خيرها ، وأعوذ بك من شرها \"[1].","key":"61-0","references":[{"number":"1","text":"أخرجه أبو داود 4/326وابن ماجه 2/1228 وانظر صحيح ابن ماجة2/ 305"}]},{"number":167,"text":"\" اللهم إني أسألك خيرها ، وخير ما فيها ، وخير ما أُرسلت به ، وأعوذ بك من شرها وشر ما فيها وشر ما أرسلت به \"[2].","key":"61-1","references":[{"number":"2","text":"مسلم 2/616 والبخاري 4/76."}]}],"extraReferences":[]},{"id":62,"title":"دعاء الرعد","url":"https://www.imadislam.com/hisnulmuslim/062.htm","entries":[{"number":168,"text":"\" سبحان الذي يُسبح الرعد بحمده والملائكة من خيفته \"[1]","key":"62-0","references":[{"number":"1","text":"كان عبد الله بن الزبير رضي الله عنهما إذا سمع الرعد ترك الحديث وقال :....\" الموطأ 2/992 وقال الألباني صحيح الإسناد موقوفاً"}]}],"extraReferences":[]},{"id":63,"title":"من أدعية الاستسقاء","url":"https://www.imadislam.com/hisnulmuslim/063.htm","entries":[{"number":169,"text":"\" اللهم اسقنا غيثاً مغيثاً مريئاً مَريعاً نافعاً غير ضار ، عاجلاً غير آجل \"[1]","key":"63-0","references":[{"number":"1","text":"أبو داود 1/303 وصححه الألباني في صحيح أبي داود1/ 216"}]},{"number":170,"text":"\" اللهم أغثنا ، اللهم أغثنا ، اللهم أغثنا \"[2].","key":"63-1","references":[{"number":"2","text":"والبخاري 1/224 ،مسلم 2/613"}]},{"number":171,"text":"\" اللهم اسق عبادك وبهائمك ، وانشر رحمتك وأحيي بلدك الميت\"[3]","key":"63-2","references":[{"number":"3","text":"أبو داود 1/305 وحسنه الألباني في صحيح أبي داود1/ 218"}]}],"extraReferences":[]},{"id":64,"title":"الدعاء إذا نزل المطر","url":"https://www.imadislam.com/hisnulmuslim/064.htm","entries":[{"number":172,"text":"\" اللهم صيباً نافعاً \"[1].","key":"64-0","references":[{"number":"1","text":"البخاري مع الفتح 2/518"}]}],"extraReferences":[]},{"id":65,"title":"الذكر بعد نزول المطر","url":"https://www.imadislam.com/hisnulmuslim/065.htm","entries":[{"number":173,"text":"\" مُطرنا بفضل الله ورحمته \"[1]","key":"65-0","references":[{"number":"1","text":"والبخاري 1/205 ،مسلم 1/83"}]}],"extraReferences":[]},{"id":66,"title":"من أدعية الاستصحاء","url":"https://www.imadislam.com/hisnulmuslim/066.htm","entries":[{"number":174,"text":"\" اللهم حوالينا ولا علينا ، اللهم على الآكامِ والظرابِ وبُطون الأودية ، ومنابت الشجر \"[1]","key":"66-0","references":[{"number":"1","text":"والبخاري 1/224 ،مسلم 2/614"}]}],"extraReferences":[]},{"id":67,"title":"دعاء رؤية الهلال","url":"https://www.imadislam.com/hisnulmuslim/067.htm","entries":[{"number":175,"text":"\" الله أكبر ،اللهم أهلِه علينا بالأمن والإيمان ، والسلامة والإسلام ،والتوفيق لما تحب ربنا وترضى ، ربنا وربك الله \"[1]","key":"67-0","references":[{"number":"1","text":"الترمذي 5/504 والدارمي بلفظه 1/336 وانظر صحيح الترمذي3/ 157"}]}],"extraReferences":[]},{"id":68,"title":"الدعاء عند إفطار الصائم","url":"https://www.imadislam.com/hisnulmuslim/068.htm","entries":[{"number":176,"text":"\" ذَهبَ الظَّمأُ، وابتلَّت العروقُ وثَبَتَ الأجرُ إنْ شاء الله\"[1].","key":"68-0","references":[{"number":"1","text":"أخرجه أبي داود 2/306 وغيره وانظر صحيح الجامع 4/209"}]},{"number":177,"text":"\" اللهم إني أسألك برحمتك التي وسعت كل شيءٍ أن تغفر لي \" [2]","key":"68-1","references":[{"number":"2","text":"أخرجه ابن ماجه 1/557 من دعاء عبد الله بن عمرو رضي الله عنهما ،وحسنه الحافظ في تخريج الأذكار انظر شرح الأذكار 4/342"}]}],"extraReferences":[]},{"id":69,"title":"الدعاء قبل الطعام","url":"https://www.imadislam.com/hisnulmuslim/069.htm","entries":[{"number":178,"text":"\" إذا أكل أحدكم الطعام فليقل: \"بِسم الله، فإن نسي في أوله فليقل: بِسمِ الله في أوله وآخره\"[1].","key":"69-0","references":[{"number":"1","text":"أخرجه أبو داود 3/347 والترمذي 4/288 وانظر صحيح الترمذي2/ 167"}]},{"number":179,"text":"\" من أطعمه الله الطعام فليقل: اللهم بارك لنا فيه وأطعمنا خيراً منه\". ومن سقاه الله لبناً فليقل: اللهم بارك لنا فيه وزدنا منه\"[2].","key":"69-1","references":[{"number":"2","text":"الترمذي 5/506 وانظر صحيح الترمذي3/ 158"}]}],"extraReferences":[]},{"id":70,"title":"الدعاء عند الفراغ من الطعام","url":"https://www.imadislam.com/hisnulmuslim/070.htm","entries":[{"number":180,"text":"\" الحمد لله الذي أطعمني هذا ،وزرقنيه ،من غير حول مني ولا قوة\"[1]","key":"70-0","references":[{"number":"1","text":"أخرجه أصحاب السنن إلا النسائي وانظر صحيح الترمذي 3/159"}]},{"number":181,"text":"\" الحمدُ لله حمداً كثيراً طيباً مباركاً فيهِ، غيْرَ [مَكْفيٍّ ولا] مُوَدَّع، ولا مُستَغنَى عَنْهُ ربّنا\"[2].","key":"70-1","references":[{"number":"2","text":"البخاري 6/‌214 والترمذي بلفظه 5/ 507"}]}],"extraReferences":[]},{"id":71,"title":"دعاء الضيف لصاحب الطعام","url":"https://www.imadislam.com/hisnulmuslim/071.htm","entries":[{"number":182,"text":"\" اللهُمَّ بَارِكْ لَهُم فيما رَزَقتهْمْ، واغْفِر لهم وارحَمْهُم \"[1].","key":"71-0","references":[{"number":"1","text":"مسلم3/ 1626"}]}],"extraReferences":[]},{"id":72,"title":"الدعاء لمن سقاه أو إذا أراد ذلك","url":"https://www.imadislam.com/hisnulmuslim/072.htm","entries":[{"number":183,"text":"\" اللهُمَّ أَطْعِمْ مَنْ أطْعَمَني وأَسْقِ مَنْ سْقَاني \"[1].","key":"72-0","references":[{"number":"1","text":"مسلم3/ 26"}]}],"extraReferences":[]},{"id":73,"title":"الدعاء إذا أفطر عند أهل بيت","url":"https://www.imadislam.com/hisnulmuslim/073.htm","entries":[{"number":184,"text":"\" أَفطَر عِنْدَكُم الصائِمونَ ، وأكل طعامَكُمُ الأبْرارُ ، وصلت عليكُمُ الملائِكَةُ \"[1].","key":"73-0","references":[{"number":"1","text":"سنن أبي داود 3/367، وابن ماجه 1/556 ،والنسائي في عمل اليوم والليلة برقم 296- 298 ،ونص على أنه صلى الله عليه وسلم يقوله إذا أفطر عند أهل بيت ،وصححه الألباني في صحيح أبي داود 2/730"}]}],"extraReferences":[]},{"id":74,"title":"دعاء الصائم إذا حضر الطعام ولم يفطر","url":"https://www.imadislam.com/hisnulmuslim/074.htm","entries":[{"number":185,"text":"\" إذا دُعي أحدكم فليجب ، فإن كان صائماً فليصل وإن كان مفطراً فليطعم \"[1] ومعنى فليصل أي فليدع .","key":"74-0","references":[{"number":"1","text":"مسلم 2/1054"}]}],"extraReferences":[]},{"id":75,"title":"ما يقول الصائم إذا سابه أحد","url":"https://www.imadislam.com/hisnulmuslim/075.htm","entries":[{"number":186,"text":"\" إني صائم ، إني صائم \"[1].","key":"75-0","references":[{"number":"1","text":"البخاري مع الفتح 4/103 ،ومسلم 2/ 806"}]}],"extraReferences":[]},{"id":76,"title":"الدعاء عند رؤية باكورة الثمر","url":"https://www.imadislam.com/hisnulmuslim/076.htm","entries":[{"number":187,"text":"\" اللهم بارك لنا في ثمرنا ، وبارك لنا في مدينتنا وبارك لنا في صاعنا ، وبارك لنا في مدنا \"[1]","key":"76-0","references":[{"number":"1","text":"مسلم 2/1000"}]}],"extraReferences":[]},{"id":77,"title":"دعاء العطاس","url":"https://www.imadislam.com/hisnulmuslim/077.htm","entries":[{"number":188,"text":"\" إذا عطس أحدكم فليقل الحمد لله ،وليقل له أخوهُ أو صاحبهُ : يرحمك الله ،فإذا قال لهُ :يرحمك الله ،فليقل :يهديكم الله ويصلح بالكم \" [1]","key":"77-0","references":[{"number":"1","text":"البخاري 7/125"}]}],"extraReferences":[]},{"id":78,"title":"ما يقالُ للكافر إذا عطس فحمد الله","url":"https://www.imadislam.com/hisnulmuslim/078.htm","entries":[{"number":189,"text":"\" يهديكم الله ويصلح بالكم \" [1]","key":"78-0","references":[{"number":"1","text":"الترمذي 5/82 وأحمد 4/400 وأبو داود 4/308، وانظر صحيح الترمذي 2/354"}]}],"extraReferences":[]},{"id":79,"title":"الدعاء للمتزوج","url":"https://www.imadislam.com/hisnulmuslim/079.htm","entries":[{"number":190,"text":"\" بارك الله لك ، وبارك عليك ، وجمع بينكما في خير \"[1] .","key":"79-0","references":[{"number":"1","text":"أخرجه أصحاب السنن إلا النسائي وانظر صحيح الترمذي 1/316"}]}],"extraReferences":[]},{"id":80,"title":"دعاء المتزوج لنفسه ودعاء شراء الدابة","url":"https://www.imadislam.com/hisnulmuslim/080.htm","entries":[{"number":191,"text":"إذا تزوج أحدكم امرأة ،أو إذا اشترى خادماً فليقل :\" اللهم إني أسألك خيرها وخير ما جبلتها عليه وأعوذ بك من شرها وشر ما جبلتها عليه ، وإذا اشترى بعيراً فليأخذ بذروة سنامه وليقل مثل ذلك \"[1]","key":"80-0","references":[{"number":"1","text":"أبو داود 2/248 وابن ماجه 1/617 وانظر صحيح ابن ماجه 1/324"}]}],"extraReferences":[]},{"id":81,"title":"الدعاء قبل إتيان الزوجة","url":"https://www.imadislam.com/hisnulmuslim/081.htm","entries":[{"number":192,"text":"\" بسم الله ، اللهم جنبنا الشيطان وجنب الشيطان ما رزقتنا \"[1]","key":"81-0","references":[{"number":"1","text":"البخاري 6/141 ومسلم 2/1028"}]}],"extraReferences":[]},{"id":82,"title":"دعاء الغضب","url":"https://www.imadislam.com/hisnulmuslim/082.htm","entries":[{"number":193,"text":"\" أعوذ بالله من الشيطان الرجيم \"[1]","key":"82-0","references":[{"number":"1","text":"البخاري 6/99 ومسلم4/2015"}]}],"extraReferences":[]},{"id":83,"title":"دعاء من رأى مبتلى","url":"https://www.imadislam.com/hisnulmuslim/083.htm","entries":[{"number":194,"text":"\" الحمد لله الذي عافاني مما ابتلاك به ، وفضلني على كثير ممن خلق تفضيلاً \"[1]","key":"83-0","references":[{"number":"1","text":"الترمذي 5/494 و5/493 وانظر صحيح الترمذي3/ 153"}]}],"extraReferences":[]},{"id":84,"title":"ما يقال في المجلس","url":"https://www.imadislam.com/hisnulmuslim/084.htm","entries":[{"number":195,"text":"عن ابن عمر قال : كان يعد لرسول الله صلى الله عليه وسلم في المجلس الواحد مائة مرة من قبل أن يقوم \"رب اغفر لي وتب علي إنك أنت التواب الغفور \"[1]","key":"84-0","references":[{"number":"1","text":"الترمذي وغيره وانظر صحيح الترمذي 3/153 وصحيح ابن ماجه 2/321 ولفظه للترمذي"}]}],"extraReferences":[]},{"id":85,"title":"كفارة المجلس","url":"https://www.imadislam.com/hisnulmuslim/085.htm","entries":[{"number":196,"text":"\" سبحانك اللهم وبحمدك ، أشهد أن لا إله إلا أنت أستغفرك وأتوب إليك \"[1].","key":"85-0","references":[{"number":"1","text":"أخرجه أصحاب السنن وانظر صحيح الترمذي 3/153، وقد ثبت عن عائشة رضي الله عنها قالت :ما جلس رسول الله صلى الله عليه وسلم مجلساً ، ولاتلى قرآناً ، ولا صلاة إلا ختم ذلك بكلمات....\" الحديث أخرجه النسائي في عمل اليوم والليلة برقم 308 ، وأحمد 6/77 وصححه الدكتور فاروق حمادة في تحقيقه لعمل اليوم والليلة للنسائي ص273 مايختم به جميع المجالس عن عائشة رضي الله عنها قالت : ماجلس رسول الله صلى الله عليه وسلم مجلساً قط ، ولا تلا قرآناً ، ولا صلى صلاة إلا ختم ذلك بكلمات قالت : فقلت : يارسول الله أراك ما تجلس ( مجلساً ) ولا تتلو قرآنا ، ولا تصلي صلاة إلا ختمت بهؤلاء الكلمات ؟ قال : نعم ( من قال خيراً خُتم له طابع على ذلك الخير ، ومن قال شراً كن له كفارة ) ، (( سبحانك وبحمدك لا إله إلا أنت أستغفرك وأتوب إليك ))."}]}],"extraReferences":[]},{"id":86,"title":"الدعاء لمن قال غفر الله لك","url":"https://www.imadislam.com/hisnulmuslim/086.htm","entries":[{"number":197,"text":"\" ولك \"[1]","key":"86-0","references":[{"number":"1","text":"أحمد 5/28 والنسائي في عمل اليوم والليلة ص218برقم 421 تحقيق الدكتور فاروق حمادة"}]}],"extraReferences":[]},{"id":87,"title":"الدعاء لمن صنع إليك معروفاً","url":"https://www.imadislam.com/hisnulmuslim/087.htm","entries":[{"number":198,"text":"\" جَزَاكَ الله خيراً \"[1].","key":"87-0","references":[{"number":"1","text":"أخرجه الترمذي رقم 2035 وانظر صحيح الجامع 6244 وصحيح الترمذي2/ 200"}]}],"extraReferences":[]},{"id":88,"title":"ما يعصم به من الدجال","url":"https://www.imadislam.com/hisnulmuslim/088.htm","entries":[{"number":199,"text":"\" من حفظ عشر آيات من أول سورة الكهف عصم من الدجال \"[1] والاستعاذة بالله من فتنتة عقب التشهد الأخير من كل صلاة .[2]","key":"88-0","references":[{"number":"1","text":"مسلم 1/555 وفي رواية من آخر الكهف 1/556"},{"number":"2","text":"انظر حديث رقم 55 وحديث 56"}]}],"extraReferences":[]},{"id":89,"title":"الدعاء لمن قال إني أحبك في الله","url":"https://www.imadislam.com/hisnulmuslim/089.htm","entries":[{"number":200,"text":"\" أحبك الذي أحببتني له ُ\"[1]","key":"89-0","references":[{"number":"1","text":"أخرجه أبو داود 4/333، وحسنه الألباني في صحيح سنن أبي داود 3/965"}]}],"extraReferences":[]},{"id":90,"title":"الدعاء لمن عرض عليك ماله","url":"https://www.imadislam.com/hisnulmuslim/090.htm","entries":[{"number":201,"text":"\" بارك الله لك في أهلك ومالك \". [1]","key":"90-0","references":[{"number":"1","text":"البخاري الفتح4/ 88"}]}],"extraReferences":[]},{"id":91,"title":"الدعاء لمن أقرض عند القضاء","url":"https://www.imadislam.com/hisnulmuslim/091.htm","entries":[{"number":202,"text":"\" بارك الله لك في أهلك ومالك إنما جزاء السلف الحمد والأداء \"[1]","key":"91-0","references":[{"number":"1","text":"أخرجه النسائي في عمل اليوم والليلة ص 300 وابن ماجه 2/ 809 وانظر صحيح ابن ماجه 2/809 وانظر صحيح ابن ماجه 2/55"}]}],"extraReferences":[]},{"id":92,"title":"دعاء الخوف من الشرك","url":"https://www.imadislam.com/hisnulmuslim/092.htm","entries":[{"number":203,"text":"\" اللهم إني أعوذ بك أن أشرك بك وأنا أعلم ، وأستغفرك لما لا أعلم \" [1]","key":"92-0","references":[{"number":"1","text":"أحمد 4/403 وغيره وانظر صحيح الجامع 3/333 وصحيح الترغيب والترهيب للألباني"}]}],"extraReferences":[]},{"id":93,"title":"الدعاء لمن قال بارك الله فيك","url":"https://www.imadislam.com/hisnulmuslim/093.htm","entries":[{"number":204,"text":"\" وفيك بارك الله \"[1]","key":"93-0","references":[{"number":"1","text":"أخرجه ابن السني ص138 برقم 278 وانظر الوابل الصيب لابن القيم 304 تحقيق بشير محمد عيون"}]}],"extraReferences":[]},{"id":94,"title":"دعاء كراهية الطيرة","url":"https://www.imadislam.com/hisnulmuslim/094.htm","entries":[{"number":205,"text":"\" اللهم لا طير إلا طيرك ، ولا خير إلا خيرك ،ولا إله غيرك \"[1]","key":"94-0","references":[{"number":"1","text":"أحمد 2/220 وابن السني برقم 292 وصححه الألباني في الأحاديث الصحيحة 3/54 رقم 1065 ، أما الفأل فكان يعجب النبي صلى الله عليه وسلم ؛ ولهذا سمع من رجل كلمة طيبة فأعجبته فقال : \"أخذنا فألك من فيك \" أبو داود وأحمد ،وصححه الألباني في الصحيحة2/363 عند أبي الشيخ في أخلاق النبي"}]}],"extraReferences":[]},{"id":95,"title":"دعاء ركوب الدابة","url":"https://www.imadislam.com/hisnulmuslim/095.htm","entries":[{"number":206,"text":"\" بسم الله. الحمد لله. {سُبْحانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ * وَإِنَّا إِلَى رَبِّنَا لَمُنقَلِبُونَ} الحمد لله ، الحمد لله ، الحمد لله ، الله اكبر ، الله اكبر ، الله اكبر ، سبحانك اللهم إني ظلمت نفسي فاغفر لي ، فإنه لا يغفر الذنوب إلا أنت \"[1].","key":"95-0","references":[{"number":"1","text":"أبو داود 3/34 والترمذي 5/501 وانظر صحيح الترمذي3/ 156"}]}],"extraReferences":[]},{"id":96,"title":"دعاء السفر","url":"https://www.imadislam.com/hisnulmuslim/096.htm","entries":[{"number":207,"text":"\"الله أكبر، الله أكبر، الله أكبر،{سُبْحانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ * وَإِنَّا إِلَى رَبِّنَا لَمُنقَلِبُونَ} \"اللهم إنا نسألُكَ في سفرنا هذا البرَّ والتقوى، ومن العمل ما ترضى، اللهم هون علينا سفرنا هذا واطو عنا بعده، اللهم أنت الصاحب في السفر، والخليفة في الأهل، اللهم إني أعوذ بك من وعْثاءِ السفر، وكآبة المنظر وسوء المنقلب في المال والأهل\" وإذا رجع قالهن وزاد فيهن \"آيبون، تائبون، عابدون، لربنا حامدون\"[1].","key":"96-0","references":[{"number":"1","text":"رواه مسلم2/ 978"}]}],"extraReferences":[]},{"id":97,"title":"دعاء دخول القرية أو البلدة","url":"https://www.imadislam.com/hisnulmuslim/097.htm","entries":[{"number":208,"text":"\" اللهم رب السموات السبع وما أظللن ، ورب الأرضين السبع وما أقللن ،ورب الشياطين وما أضللن ، ورب الرياح وما ذرين.أسألك خير هذه القرية وخير أهلها ، وخير ما فيها،وأعوذ بك من شرها،وشر أهلها ، وشر ما فيها\"[1]","key":"97-0","references":[{"number":"1","text":"الحاكم وصححه ووافقه الذهبي 2/100 وابن السني برقم 524وحسنه الحافظ في تخريج الأذكار 5/154 قال ابن باز:ورواه النسائي بإسناد حسن . انظر تحفة الأخيار ص 37"}]}],"extraReferences":[]},{"id":98,"title":"دعاء دخول السوق","url":"https://www.imadislam.com/hisnulmuslim/098.htm","entries":[{"number":209,"text":"\" لا إله إلا الله وحده لا شريك له ، له الملك وله الحمد ، يُحيي ويُميت ، وهو حي لا يموت ، بيده الخير وهو على كل شئ قدير \"[1].","key":"98-0","references":[{"number":"1","text":"الترمذي 5/491 والحاكم 1/538 وحسنه الألباني في صحيح ابن ماجه 2/21 وفي صحيح الترمذي3/ 152"}]}],"extraReferences":[]},{"id":99,"title":"الدعاء إذا تعس المركوب","url":"https://www.imadislam.com/hisnulmuslim/099.htm","entries":[{"number":210,"text":"\" بسم الله \" [1]","key":"99-0","references":[{"number":"1","text":"أبو داود 4/296 وصححه الألباني في صحيح أبي داود 3/941"}]}],"extraReferences":[]},{"id":100,"title":"دعاء المسافر للمقيم","url":"https://www.imadislam.com/hisnulmuslim/100.htm","entries":[{"number":211,"text":"\" أستودعُكَ الله الذي لا تضيع ودائعه \"[1].","key":"100-0","references":[{"number":"1","text":"أحمد 2/403 وابن ماجه 2/943 وانظر صحيح ابن ماجة2/ 133"}]}],"extraReferences":[]},{"id":101,"title":"دعاء المقيم للمسافر","url":"https://www.imadislam.com/hisnulmuslim/101.htm","entries":[{"number":212,"text":"\" أستودع الله دينك وأمانتك ،وخواتيم عملك \"[1].","key":"101-0","references":[{"number":"1","text":"أحمد 2/7 الترمذي5/499 وانظر صحيح الترمذي3/ 155"}]},{"number":213,"text":"\" زوَّدك الله التقوى، وغفر ذْنبك ويسَّر لك الخير حيث ما كنت \".[2]","key":"101-1","references":[{"number":"2","text":"الترمذي وانظر صحيح الترمذي3/ 155"}]}],"extraReferences":[]},{"id":102,"title":"التكبير والتسبيح في سير السفر","url":"https://www.imadislam.com/hisnulmuslim/102.htm","entries":[{"number":214,"text":"قال جابر رضي الله عنه : \" كنا إذا صعدنا كبرنا ، وإذا نزلنا سبحنا \"[1].","key":"102-0","references":[{"number":"1","text":"البخاري الفتح6/ 135"}]}],"extraReferences":[]},{"id":103,"title":"دعاء المسافر إذا أسحر","url":"https://www.imadislam.com/hisnulmuslim/103.htm","entries":[{"number":215,"text":"\" سَمعَ سَامعً بحمد الله وحُسنِ بلائه علينا، ربنا صاحبنا ، وأفضِل علينا عائذا بالله من النار\"[1].","key":"103-0","references":[{"number":"1","text":"مسلم4/ 2086 ومعني سمع سامع : أي شهد شاهد على حمدنا لله تعالى على نعمه وحسن بلائه . ومعني سمع سامع : بلغ سامع قولي هذا لغيره وقال مثله تنبيهاً على الذكر في السحر والدعاء . وقوله : ربنا صاحبنا وأفضل علينا : أي احفظنا وحطنا واكلأنا وأفضل علينا بجزيل نعمك واصرف عنا كل مكروه ، شرح النووي 17/39"}]}],"extraReferences":[]},{"id":104,"title":"الدعاء إذا نزل منزلا في سفر أو غيره","url":"https://www.imadislam.com/hisnulmuslim/104.htm","entries":[{"number":216,"text":"\" أعوذ بكلمات الله التامات من شر ما خلق \"[1]","key":"104-0","references":[{"number":"1","text":"رواه مسلم4/2080"}]}],"extraReferences":[]},{"id":105,"title":"ذكر الرجوع من السفر","url":"https://www.imadislam.com/hisnulmuslim/105.htm","entries":[{"number":217,"text":"\" يكبر على كل شرف ثلاث تكبيرات ثم يقول : لا إله إلا الله وحده لا شريك لهُ ،لهُ الملك ، ولهُ الحمدُ وهو على كل شيءٍ قدير ، آيبون ،تائبون ، عابدون ، لربنا حامدون ،صدق الله وعده،ونصر عبده،وهزم الأحزاب وحده\"[1]","key":"105-0","references":[{"number":"1","text":"كان النبي صلى الله عليه وسلم يقوله إذا قفل من غزو أو حج ، البخاري 7/163 ومسلم 2/ 980"}]}],"extraReferences":[]},{"id":106,"title":"ما يقول ويفعل من أتاه أمر يسره أو يكرهه","url":"https://www.imadislam.com/hisnulmuslim/106.htm","entries":[{"number":218,"text":"كان صلى الله عليه وسلم إذا أتاه الأمر يسره قال :\" الحمد لله الذي بنعمته تتم الصالحات \" و إذا أتاه أمر يكرهه قال : \" الحمد لله على كل حال \"[1]","key":"106-0","references":[{"number":"1","text":"أخرجه ابن السني في عمل اليوم والليلة والحاكم وصححه 1/499 وصححه الألباني في صحيح الجامع 4/ 201"}]}],"extraReferences":[]},{"id":107,"title":"فضل الصلاة على النبي صلى الله عليه وسلم","url":"https://www.imadislam.com/hisnulmuslim/107.htm","entries":[{"number":219,"text":"قال صلى الله عليه وسلم \" من صلى علي صلاة صلى الله عليه بها عشراً \" [1]","key":"107-0","references":[{"number":"1","text":"أخرجه مسلم 1/288"}]},{"number":220,"text":"وقال صلى الله عليه وسلم : \" لا تجعلوا قبري عيداً وصلوا علي ؛ فإن صلاتكم تبلغني حيث كنتم \" [2].","key":"107-1","references":[{"number":"2","text":"أبو داود 2/218 وأحمد 2/367 وصححه الألباني في صحيح أبي داود 2/ 383"}]},{"number":221,"text":"وقال صلى الله عليه وسلم : \" البخيل من ذكرت عندهُ فلم يصل علي \"[3]","key":"107-2","references":[{"number":"3","text":"الترمذي 5/551 وغيره وانظر صحيح الجامع 3/ 25 وصحيح الترمذي 3/ 177"}]},{"number":222,"text":"وقال صلى الله عليه وسلم \" إن لله ملائكة سياحين في الأرض يبلغوني من أمتي السلام \"[4]","key":"107-3","references":[{"number":"4","text":"النسائي ،والحاكم 2/421 وصححه الألباني في صحيح النسائي 1/274"}]},{"number":223,"text":"وقال صلى الله عليه وسلم \" ما من أحدٍ يسلِّمُ عليَّ إلَّا ردَّ اللَّهُ عليَّ روحي حتَّى أردَّ عليْهِ السَّلامَ \"[5]","key":"107-4","references":[{"number":"5","text":"أبو داود برقم 2041وحسنه الألباني في صحيح أبي داود 1/ 383"}]}],"extraReferences":[]},{"id":108,"title":"إفشاء السلام","url":"https://www.imadislam.com/hisnulmuslim/108.htm","entries":[{"number":224,"text":"قال رسول الله صلى الله عليه وسلم :\" لا تدخلوا الجنة حتى تؤمنوا ، ولا تؤمنوا حتى تحابوا ، أو لا أدلكم على شيءٍ إذا فعلتموه تحاببتم ، أفشوا السلام بينكم \"[1]","key":"108-0","references":[{"number":"1","text":"مسلم 1/74 وغيره"}]},{"number":225,"text":"ثلاث من جمعهن فقد جمع الإيمان : الإنصاف من نفسك ، وبذل السلام للعالم ،والإنفاق من الإقتار \" [2]","key":"108-1","references":[{"number":"2","text":"البخاري مع الفتح 1/ 82 عن عمار رضي الله عنه موقوفاً معلقاً"}]},{"number":226,"text":"وعن عبد الله بن عمر رضي الله عنهما : أن رجلاً سأل النبي صلى الله عليه وسلم أي الإسلام خير قال :\" تطعم الطعام وتقرأ السلام على من عرفت ومن لم تعرف \" [3]","key":"108-2","references":[{"number":"3","text":"البخاري مع الفتح 1/55 ومسلم 1/65."}]}],"extraReferences":[]},{"id":109,"title":"كيف يرد السلام على الكافر إذا سلم","url":"https://www.imadislam.com/hisnulmuslim/109.htm","entries":[{"number":227,"text":"إذا سلم عليكم أهل الكتاب فقولوا : \" وعليكم \"[1]","key":"109-0","references":[{"number":"1","text":"البخاري مع الفتح11/42 ،ومسلم 4/1705"}]}],"extraReferences":[]},{"id":110,"title":"دعاء صياح الديك ونهيق الحمار","url":"https://www.imadislam.com/hisnulmuslim/110.htm","entries":[{"number":228,"text":"\" إذا سمعتم صياح الديكة ، فاسألوا الله من فضله فإنها رأت ملكاً وإذا سمعتم نهيق الحمار ، فتعوذوا بالله من الشيطان فإنه رأى شيطاناً \"[1].","key":"110-0","references":[{"number":"1","text":"البخاري مع الفتح6/350 ،ومسلم 4/2092"}]}],"extraReferences":[]},{"id":111,"title":"دعاء نباح الكلاب بالليل","url":"https://www.imadislam.com/hisnulmuslim/111.htm","entries":[{"number":229,"text":"\" إذا سمعتم نُباح الكلاب ونهيق الحمير بالليل فتعوذوا بالله منهن فإنهن يرين ما لا ترون \"[1].","key":"111-0","references":[{"number":"1","text":"أبو داود 4/ 327 وأحمد 3/ 306 وصححه الألباني في صحيح أبي داود3/ 961"}]}],"extraReferences":[]},{"id":112,"title":"الدعاء لمن سببته","url":"https://www.imadislam.com/hisnulmuslim/112.htm","entries":[{"number":230,"text":"قال صلى الله عليه وسلم: \" اللَّهُم فأيما مؤمن سببته فاجعل ذلك له قربة إليك يوم القيامة \"[1].","key":"112-0","references":[{"number":"1","text":"البخاري مع الفتح 11/ 171 و مسلم4/ 2007 ولفظه فاجعلها له زكاة ورحمة"}]}],"extraReferences":[]},{"id":113,"title":"ما يقول المسلم إذا مدح المسلم","url":"https://www.imadislam.com/hisnulmuslim/113.htm","entries":[{"number":231,"text":"قال صلى الله عليه وسلم : \" إذا كان أحدكم مادحاً صاحبه لا محالة فليقل : أحسبُ فلاناً والله حسيبهُ ولا أزكي على الله أحداً ، أحسبهُ — إن كان يعلم ذاك — كذا وكذا \" [1]","key":"113-0","references":[{"number":"1","text":"رواه مسلم 4/2296"}]}],"extraReferences":[]},{"id":114,"title":"ما يقول المسلم إذا زكي","url":"https://www.imadislam.com/hisnulmuslim/114.htm","entries":[{"number":232,"text":"\" اللهم لا تؤاخذني بما يقولون ، واغفر لي مالا يعلمون [واجعلني خيراً مما يظنون]\"[1]","key":"114-0","references":[{"number":"1","text":"البخاري في الأدب المفرد برقم 761 ، وصحح إسناده الألباني في صحيح الأدب المفرد برقم 585 ، وما بين المعكوفين زيادة للبيهقي في شعب الإيمان 4/ 228 من طريق آخر ."}]}],"extraReferences":[]},{"id":115,"title":"كيف يلبي المحرم في الحج أو العمرة","url":"https://www.imadislam.com/hisnulmuslim/115.htm","entries":[{"number":233,"text":"\" لبيك اللهم لبيك ، لبيك لا شريك لك لبيك ، إن الحمد والنعمة لك والملك ، لا شريك لك \"[1]","key":"115-0","references":[{"number":"1","text":"البخاري مع الفتح 3/ 408 ، ومسلم 2/841"}]}],"extraReferences":[]},{"id":116,"title":"التكبيرة إذا أتي الركن الأسود","url":"https://www.imadislam.com/hisnulmuslim/116.htm","entries":[{"number":234,"text":"\" طاف النبي صلى الله عليه وسلم بالبيت على بعير كلما أتي الركن أشار إليه بشيء عنده وكبر \" [1]","key":"116-0","references":[{"number":"1","text":"البخاري مع الفتح 3/476 ،والمراد بالشيء المحجن انظر : البخاري مع الفتح 3/472."}]}],"extraReferences":[]},{"id":117,"title":"الدعاء بين الركن اليماني والحجر الأسود","url":"https://www.imadislam.com/hisnulmuslim/117.htm","entries":[{"number":235,"text":"{ رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ}[1]","key":"117-0","references":[{"number":"1","text":"أبو داود 2/ 179 وأحمد 3/411 والبغوي في شرح السنة 7/128 ،وحسنه الألباني في صحيح أبي داود 1/ 354 ، والآية من سورة البقرة ، 201"}]}],"extraReferences":[]},{"id":118,"title":"دعاء الوقوف على الصفا والمروة","url":"https://www.imadislam.com/hisnulmuslim/118.htm","entries":[{"number":236,"text":"فلما دنا صلى الله عليه وسلم من الصفا قرأ: { إِنَّ الصَّفَا وَالْمَرْوَةَ مِن شَعَآئِرِ اللّهِ } \" أبدأ بما بدأ الله به \" فبدأ بالصفا فرقي عليه حتى رأى البيت فاستقبل القبلة ، فوحد الله وكبره وقال : \" لا إله إلا الله وحده لا شريك لهُ ، لهُ الملك ولهُ الحمد وهو على كل شيءٍ قدير ، لا إله إلا الله وحده ، أنجز وعده ، ونصر عبده ، وهزم الأحزاب وحده \" ثم دعا بين ذلك . قال مثل هذا ثلاث مرات \" الحديث وفيه \" ففعل على المروة كما فعل على الصفا \" [1]","key":"118-0","references":[{"number":"1","text":"مسلم 2/888"}]}],"extraReferences":[]},{"id":119,"title":"الدعاء يوم عرفة","url":"https://www.imadislam.com/hisnulmuslim/119.htm","entries":[{"number":237,"text":"\" خير الدعاء دعاء يوم عرفة ، وخيرُ ما قلت أنا والنبيُّون من قبلي : لا إله إلا الله وحدهُ لا شريك لهُ ، لهُ الملكُ ولهُ الحمدُ وهو على كل شيء قدير\" [1]","key":"119-0","references":[{"number":"1","text":"الترمذي وحسنه الألباني في صحيح الترمذي 3/184، وفي الحديث الصحيحة 4/6"}]}],"extraReferences":[]},{"id":120,"title":"الذكر عند المشعر الحرام","url":"https://www.imadislam.com/hisnulmuslim/120.htm","entries":[{"number":238,"text":"\" ركب صلى الله عليه وسلم القصواء حتى أتى المشعر الحرام فاستقبل القبلة ( فدعاه ُ، وكبرهُ ،وهللهُ ، ووحدهُ) فلم يزل واقفاً حتى أسفر جداً فدفع قبل أن تطلع الشمس \"[1]","key":"120-0","references":[{"number":"1","text":"مسلم 2/891"}]}],"extraReferences":[]},{"id":121,"title":"التكبيرة عند رمي الجمار مع كل حصاة","url":"https://www.imadislam.com/hisnulmuslim/121.htm","entries":[{"number":239,"text":"\"يكبر كلما رمى بحصاة عند الجمار الثلاث ثم يتقدم، ويقف يدعو مستقبل القبلة، رافعاً يديه بعد الجمرة الأولى والثانية، أما جمرة العقبة فيرميها ويكبر عند كل حصاة وينصرف ولا يقف عندها \"[1]","key":"121-0","references":[{"number":"1","text":"البخاري مع الفتح 3/583 و3/584 وانظر لفظه هناك . والبخاري مع الفتح 3/581 ورواه مسلم أيضاً"}]}],"extraReferences":[]},{"id":122,"title":"ما يقول عند التعجب والأمر السار","url":"https://www.imadislam.com/hisnulmuslim/122.htm","entries":[{"number":240,"text":"\" سبحان الله \"[1]","key":"122-0","references":[{"number":"1","text":"البخاري مع الفتح 1/210 و390 و414 ومسلم 4/ 1857."}]},{"number":241,"text":"\" الله أكبر \"[2]","key":"122-1","references":[{"number":"2","text":"البخاري الفتح8/ 441 وانظر صحيح الترمذي 2/103 و2/235 ومسند أحمد 5/ 218"}]}],"extraReferences":[]},{"id":123,"title":"ما يفعل من أتاه أمر يسره","url":"https://www.imadislam.com/hisnulmuslim/123.htm","entries":[{"number":242,"text":"\" كان النبي صلى الله عليه وسلم إذا أتاه أمر يسرهُ أو يسرُّ به خر ساجداً شكراً لله تبارك وتعالى \" [1]","key":"123-0","references":[{"number":"1","text":"رواه أهل السنن إلا النسائي . انظر صحيح ابن ماجه 1/ 233 وإرواء الغليل 2/226"}]}],"extraReferences":[]},{"id":124,"title":"ما يقول من أحس وجعاً في جسده","url":"https://www.imadislam.com/hisnulmuslim/124.htm","entries":[{"number":243,"text":"\" ضع يدك على الذي تألم من جسدك وقل: بسم الله ، ثلاثاً وقل سبع مرات : \" أعوذ بالله وقدرته من شر ما أجد وأحاذر\" [1]","key":"124-0","references":[{"number":"1","text":"مسلم 4/1728"}]}],"extraReferences":[]},{"id":125,"title":"دعاء من خشي أن يصيب شيئاً بعينه","url":"https://www.imadislam.com/hisnulmuslim/125.htm","entries":[{"number":244,"text":"\" إذا رأى أحدكم من أخيه ، أو من نفسه ، أومن ماله ما يعجبهُ [فليدع لهُ بالبركة ] فإن العين حقٌّ \"[1]","key":"125-0","references":[{"number":"1","text":"مسند أحمد 4/447 وابن ماجه ومالك ، وصححه الألباني في صحيح الجامع 1/212 وانظر تحقيق زاد المعاد للأرناؤوط 4/170"}]}],"extraReferences":[]},{"id":126,"title":"ما يقال عند الفزع","url":"https://www.imadislam.com/hisnulmuslim/126.htm","entries":[{"number":245,"text":"\" لا إله إلا الله \"[1]","key":"126-0","references":[{"number":"1","text":"البخاري مع الفتح 6/ 181 ، ومسلم 4/ 2208 ."}]}],"extraReferences":[]},{"id":127,"title":"ما يقول عند الذبح أو النحر","url":"https://www.imadislam.com/hisnulmuslim/127.htm","entries":[{"number":246,"text":"\" بسم الله والله أكبر [ اللهم منك ولك ] اللهم تقبل مني \"[1].","key":"127-0","references":[{"number":"1","text":"مسلم 3/1557 والبيهقي 9/287 وما بين المعكوفين للبيهقي 9/287 وغيره والجملة الأخيرة سقتها بالمعنى من رواية مسلم ."}]}],"extraReferences":[]},{"id":128,"title":"ما يقول لرد كيد مردة الشياطين","url":"https://www.imadislam.com/hisnulmuslim/128.htm","entries":[{"number":247,"text":"\" أعوذ بكلمات الله التامات التي لا يجاوزهن بر ولا فاجر من شر ما خلق ، وبرأ وذرأ ومن شر ما ينزل من السماء ، ومن شر ما يعرج فيها ، ومن شر ما ذرأ في الأرض ، ومن شر ما يخرج منها ، ومن شر فتن الليل والنهار ، ومن شر كل طارق إلا طارقاً يطرق بخير يا رحمن \"[1]","key":"128-0","references":[{"number":"1","text":"أحمد 3/419 بإسناد صحيح وابن السني برقم 637 وصحح إسناده الأرناؤوط في تخريجه للطحاوية ص 133 وانظر مجمع الزوائد 10/ 127."}]}],"extraReferences":[]},{"id":129,"title":"الاستغفار والتوبة","url":"https://www.imadislam.com/hisnulmuslim/129.htm","entries":[{"number":248,"text":"قال رسول الله صلى الله عليه وسلم :\" والله إني لاستغفر الله وأتوب إليه في اليوم أكثر من سبعين مرة \"[1] .","key":"129-0","references":[{"number":"1","text":"البخاري مع الفتح 11/101"}]},{"number":249,"text":"وقال صلى الله عليه وسلم :\" يا أيها الناس توبوا إلى الله فإني أتوب في اليوم إليه مائة مرةً \"[2]","key":"129-1","references":[{"number":"2","text":"مسلم 4/2076"}]},{"number":250,"text":"وقال صلى الله عليه وسلم :\" من قال أستغفر الله العظيم الذي لا إله إلا هو الحي القيوم وأتوب إليه ، غفر الله لهُ وإن كان فر من الزحف \"[3]","key":"129-2","references":[{"number":"3","text":"أخرجه أبو داود 2/85 والترمذي 5/569 والحاكم وصححه ووافقه الذهبي 1/511 وصححه الألباني . انظر صحيح الترمذي 3/182 وجامع الأصول لأحاديث الرسول صلى الله عيه وسلم 4/389 — 390 بتحقيق الأرناؤوط"}]},{"number":251,"text":"وقال صلى الله عليه وسلم :\" أقرب ما يكون الربُّ من العبد في جوف الليل الآخر فإن استطعت أن تكون ممن يذكر الله في تلك الساعة فكن \" [4]","key":"129-3","references":[{"number":"4","text":"أخرجه الترمذي والنسائي 1/279 والحاكم وانظر صحيح الترمذي 3/183 وجامع الأصول بتحقيق الأرناؤوط 4/144"}]},{"number":252,"text":"وقال صلى الله عليه وسلم :\" أقرب ما يكون العبد من ربه وهو ساجد فأكثروا الدعاء \" [5]","key":"129-4","references":[{"number":"5","text":"مسلم 1/350 ."}]},{"number":253,"text":"وقال صلى الله عليه وسلم :\" إنه ليغان على قلبي وإني لاستغفرُ الله في اليوم مائة مرة \"[6].","key":"129-5","references":[{"number":"6","text":"أخرجه مسلم 4/2075 قال ابن الأثير : ( ليُغان على قلبي ) أي ليغطى ويغشى والمراد : السهو ؛ لأنه كان صلى الله عليه وسلم لا يزال في مزيد من الذكر والقربة ودوام المراقبة فإذا سها عن شيء منها في بعض الأوقات ،أو نسي ،عدهُ ذنباً على نفسه ففزع إلى الاستغفار . انظر جامع الأصول 4/386"}]}],"extraReferences":[]},{"id":130,"title":"فضل التسبيح والتحميد ، والتهليل ، والتكبير","url":"https://www.imadislam.com/hisnulmuslim/130.htm","entries":[{"number":254,"text":"\" قال صلى الله عليه وسلم من قال سبحان الله وبحمده في يوم مائة مرة حطت خطاياه ولو كانت مثل زبد البحر[1]","key":"130-0","references":[{"number":"1","text":"البخاري 7/168 ومسلم 4/ 2071 ، وانظر :فضل من قالها مائة مرة إذا أصبح وإذا أمسى"}]},{"number":255,"text":"وقال صلى الله عليه وسلم :\" من قال لا إله إلا الله وحده لا شريك لهُ ، لهُ الملك ، ولهُ الحمدُ ، وهو على كل شيء قدير عشر مرات . كان كمن أعتق أربعة أنفس من ولد إسماعيل \"[2]","editorialNote":"صُحّح سقوط لفظ الجلالة في أصل الصفحة بمقابلة صحيح البخاري، الحديث ٦٤٠٣.","editorialUrl":"https://sunnah.com/bukhari/80/98","key":"130-1","references":[{"number":"2","text":"البخاري 7/67 ومسلم بلفظه 4/2071 وانظر فضل من قالها في اليوم مائة مرة"}]},{"number":256,"text":"وقال صلى الله عليه وسلم :\" كلمتان خفيفتان على اللسان ، ثقيلتان في الميزان حبيبتان إلى الرحمن : سبحان الله وبحمده سبحان الله العظيم \" [3]","key":"130-2","references":[{"number":"3","text":"البخاري 7/167ومسلم 4/2072"}]},{"number":257,"text":"وقال صلى الله عليه وسلم :\" لأن أقول سبحان الله ، والحمد لله ،ولا إله إلا الله ، والله أكبر ،أحب إلى مما طلعت عليه الشمس \" [4]","key":"130-3","references":[{"number":"4","text":"مسلم 4/2072"}]},{"number":258,"text":"وقال صلى الله عليه وسلم:\" أيعجز أحدكم أن يكسب كل يوم ألف حسنة\"فسأله سائل من جلسائه كيف يكسب أحدنا ألف حسنة ؟ قال :\" يسبح مائة تسبيحة ، فيكتب له ألف حسنة أو يحط عنه ُ ألف خطيئة \" [5]","key":"130-4","references":[{"number":"5","text":"مسلم 4/2073"}]},{"number":259,"text":"\" من قال سبحان الله العظيم وبحمده غرست له نخلة في الجنة \" [6]","key":"130-5","references":[{"number":"6","text":"أخرجه الترمذي 5/511 والحاكم 1/501 وصححه ووافقه الذهبي ، وانظر صحيح الجامع 5/531 وصحيح الترمذي 3/160 ."}]},{"number":260,"text":"وقال صلى الله عليه وسلم:\" يا عبد الله بن قيس ألا أدلك على كنز من كنوز الجنة ؟\" فقلت:بلى يا رسول الله ، قال :\" قل لا حول ولا قوة إلا بالله \"[7]","key":"130-6","references":[{"number":"7","text":"البخاري مع الفتح 11/ 213 ومسلم 4/2076"}]},{"number":261,"text":"وقال صلى الله عليه وسلم:\" أحب الكلام إلى الله أربعٌ : سبحان الله ، والحمد لله ، ولا إله إلا الله ، والله أكبر ، لا يضرك بأيهنَّ بدأت \"[8]","key":"130-7","references":[{"number":"8","text":"مسلم 3/1685"}]},{"number":262,"text":"جاء أعرابي إلى رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فقال: علمني كلاماً أقوله : قال \" قل لا إله إلا الله وحده لا شريك لهً ،الله أكبرُ كبيراً ، والحمد لله كثيراً ، سبحان الله رب العالمين ،لا حول ولا قوة إلا بالله العزيز الحكيم \" قال فهؤلاء لربي فما لي ؟ قال : \" قل: اللهم اغفر لي ،وارحمني ،واهدني وارزقني \" [9]","key":"130-8","references":[{"number":"9","text":"مسلم 4/ 2072 وزاد أبو داود : فلما ولى الأعرابي قال النبي صلى الله عليه وسلم :\" لقد ملأ يديه من الخير \"1/ 220 ."}]},{"number":263,"text":"كان الرجل إذا أسلم علمه النبي صلى الله عليه وسلم الصلاة ثم أمره أن يدعو بهؤلاء الكلمات :\" اللهم اغفر لي، وارحمني ،واهدني ، وعافني وارزقني \"[10]","key":"130-9","references":[{"number":"10","text":"مسلم 4/2073 وفي رواية لمسلم \" فإن هؤلاء تجمع لك ديناك وآخرتك \""}]},{"number":264,"text":"\" إن أفضل الذكر لا إله إلا الله \"[11] .","key":"130-10","references":[{"number":"11","text":"الترمذي 5/462 وابن ماجه 2/1249 والحاكم 1/503 وصححه ووافقه الذهبي وانظر صحيح الجامع 1/ 362"}]},{"number":265,"text":"\" الباقيات الصالحات : سبحان الله والحمد لله ، ولا إله إلا الله ،والله أكبر ،و لا حول ولا قوة إلا بالله \"[12]","key":"130-11","references":[{"number":"12","text":"أحمد برقم 513 بترتيب أحمد شاكر وإسناده صحيح وانظر مجمع الزوائد 1/297، وعزاه ابن حجر في بلوغ المرام من رواية أبي سعيد إلىالنسائي وقال :صححه ابن حبان والحاكم"}]}],"extraReferences":[]},{"id":131,"title":"كيف كان النبي صلى الله عليه وسلم يسبح ؟","url":"https://www.imadislam.com/hisnulmuslim/131.htm","entries":[{"number":266,"text":"عن عبد الله بن عمرو رضي الله عنهما قال : \" رأيت النبي صلى الله عليه وسلم يعقد التسبيح بيمينه \"[1]","key":"131-0","references":[{"number":"1","text":"أخرجه أبو داود بلفظه 2/81 والترمذي 5/521 وانظر صحيح الجامع 4/271 برقم 4865"}]}],"extraReferences":[]},{"id":132,"title":"من أنواع الخير والآداب الجامعة","url":"https://www.imadislam.com/hisnulmuslim/132.htm","entries":[{"number":267,"text":"\" إذا كان جنح الليل — أو أمسيتم — فكفوا صبيانكم ؛ فإن الشياطين تنتشر حينئذ ، فإذا ذهب ساعة من الليل فخلوهم ،وأغلقوا الأبواب واذكروا اسم الله ؛ فإن الشيطان لا يفتح باباً مغلقاً ، وأوكوا قربكم واذكروا اسم الله ، وخمروا آنيتكم واذكروا اسم الله ، ولو أن تعرضوا عليها شيئاً ، وأطفئوا مصابيحكم \"[1]","key":"132-0","references":[{"number":"1","text":"البخاري مع الفتح 10/ 88 ومسلم 3/1595. وصلى الله وسلم وبارك على نبينا محمد وعلى آله وأصحابه أجمعين ."}]}],"extraReferences":[]}],"virtue":{"id":"virtue","title":"فضل الذكر","url":"https://www.imadislam.com/hisnulmuslim/fazlolzkr.htm","entries":[{"number":null,"text":"قال الله تعالى:{ فَاذْكُرُونِي أَذْكُرْكُمْ وَاشْكُرُواْ لِي وَلاَ تَكْفُرُونِ }[1]{ يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا اللَّهَ ذِكْراً كَثِيراً}[2] { وَالذَّاكِرِينَ اللَّهَ كَثِيراً وَالذَّاكِرَاتِ أَعَدَّ اللَّهُ لَهُم مَّغْفِرَةً وَأَجْراً عَظِيماً}[3] { وَاذْكُر رَّبَّكَ فِي نَفْسِكَ تَضَرُّعاً وَخِيفَةً وَدُونَ الْجَهْرِ مِنَ الْقَوْلِ بِالْغُدُوِّ وَالآصَالِ وَلاَ تَكُن مِّنَ الْغَافِلِينَ }[4] وقال صلى الله عليه وسلم :\" مثل الذي يذكر ربه والذي لا يذكر ربه مثل الحي والميت \"[5] وقال صلى الله عليه وسلم :\" ألا أنبئكم بخير أعمالكم ،وأزكاها عند مليككم، وأرفعها في درجاتكم ، وخير لكم من إنفاق الذهب والورق ، وخير لكم من أن تلقوا عدوكم فتضربوا أعناقهم ويضربوا أعناقكم ؟\" قالوا بلى .قال : \"ذكر الله تعالى \"[6] وقال صلى الله عليه وسلم :\" يقول الله تعالى : أنا عند ظن عبدي بي ، وأنا معه إذا ذكرني ، فإن ذكرني في نفسه ذكرتهُ في نفسي ، وإن ذكرني في ملأ ذكرته في ملأ خير منهم ،وإن تقرب إلي شبراً تقربت إليه ذراعاً ،وإن تقرب إلي ذراعاً تقربت إليه باعاً ، وإن أتاني يمشي أتيتهُ هرولة \"[7] .وعن عبد الله بن بسرٍ رضي الله عنهُ أن رجلاً قال : يا رسول الله إن شرائع الإسلام قد كثرت علي فأخبرني بشيءٍ أتشبث به. قال صلى الله عليه وسلم :\" لا يزال لسانك رطباً من ذكر الله \"[8] وقال صلى الله عليه وسلم:\" من قرأ حرفاً من كتاب الله فله به حسنة ،والحسنة بعشر أمثالها ، لا أقول : {الم } حرف؛ ولكن : ألف حرف ،ولام حرف ،وميم حرف \"[9]. وعن عقبة بن عامر رضي الله عنه قال : خرج رسول الله صلى الله عليه وسلم ونحن في الصفة فقال :\" أيكم يحب أن يغدو كل يوم إلى بطحان أو إلى العقيق فيأتي منه بناقتين كوماوين في غير إثم ولا قطيعة رحم ؟\" فقلنا : يا رسول الله نحب ذلك . قال :\" أفلا يغدو أحدكم إلى المسجد فيعلم ، أو يقرأ آيتين من كتاب الله عز وجل خير له من ناقتين ، وثلاث خير لهُ من ثلاث ٍ، وأربع خير لهُ من أربع ، ومن أعدادهن من الإبل\"[10] وقال صلى الله عليه وسلم:\" من قعد مقعداً لم يذكر الله فيه كانت عليه من الله ترة ومن اضطجع مضجعاً لم يذكر الله فيه كانت عليه من الله ترة\"[11] .","key":"virtue-0","references":[{"number":"1","text":"سورة البقرة آية :152"},{"number":"2","text":"سورة الأحزاب آية : 41"},{"number":"3","text":"سورة الأحزاب آية :35"},{"number":"4","text":"سورة الأعراف ،آية :205"},{"number":"5","text":"البخاري مع الفتح 11/208 ومسلم بلفظ \"مثل البيت الذي يذكر الله فيه والبيت الذي لا يذكر الله فيه مثل الحي والميت \" 1/539"},{"number":"6","text":"الترمذي 5/459 وابن ماجه 2/1245 وانظر صحيح ابن ماجه 2/316 وصحيح الترمذي 3/139 ."},{"number":"7","text":"البخاري 8\\171 ومسلم 4\\ 2061 واللفظ للبخاري ."},{"number":"8","text":"الترمذي 5/458 وابن ماجه 2\\1246 وانظر صحيح الترمذي 3\\ 139 وصحيح ابن ماجه 2\\ 317"},{"number":"9","text":"الترمذي 5/175 وانظر صحيح الترمذي 3\\9 وصحيح الجامع الصغير 5\\340 ."},{"number":"10","text":"مسلم 1/553."},{"number":"11","text":"أبو داود 4\\264 وغيره وانظر صحيح الجامع 5\\342."}]},{"number":null,"text":"وقال صلى الله عليه وسلم : \" ما جلس قوم مجلساً لم يذكروا الله فيه ، ولم يصلوا على نبيهم إلا كان عليهم ترة ، فإن شاء عذبهم وإن شاء غفر لهم \"[12] .","key":"virtue-1","references":[{"number":"12","text":"الترمذي وانظر صحيح الترمذي 3/140"}]},{"number":null,"text":"وقال صلى الله عليه وسلم :\" ما من قوم يقومون من مجلس لا يذكرون الله فيه إلا قاموا عن مثل جيفة حمار وكان لهم حسرة \"[13].","key":"virtue-2","references":[{"number":"13","text":"أبو داود 4\\264 وانظر صحيح الجامع 5\\176."}]}],"extraReferences":[]},"source":"https://www.imadislam.com/hisnulmuslim/","retrieved":"2026-10-09","author":"سعيد بن علي بن وهف القحطاني"};
